t["'No need to panic-buy.' Somebody printed that with a straight face."] = "\\u0644\\u0627 \\u062F\\u0627\\u0639\\u064A \\u0644\\u0644\\u0647\\u0644\\u0639 \\u0628\\u0627\\u0644\\u0634\\u0631\\u0627. \\u062D\\u062F\\u0627 \\u0637\\u0628\\u0639 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0648\\u0647\\u0648 \\u0645\\u0648 \\u0636\\u0627\\u062D\\u0643."
t["'Please ration purchases.' The county's honor system has seen better days."] = "\\u0627\\u0644\\u0631\\u062C\\u0627\\u0621 \\u062A\\u0642\\u0646\\u064A\\u0646 \\u0627\\u0644\\u0645\\u0634\\u062A\\u0631\\u064A\\u0627\\u062A. \\u0634\\u0631\\u0641 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0634\\u0627\\u0641 \\u0623\\u064A\\u0627\\u0645 \\u0623\\u062D\\u0633\\u0646."
t["'Serving the community since 1948.' Service is currently self-directed."] = "\\u0628\\u062E\\u062F\\u0645\\u0629 \\u0627\\u0644\\u0623\\u0647\\u0627\\u0644\\u064A \\u0645\\u0646 1948. \\u0627\\u0644\\u062E\\u062F\\u0645\\u0629 \\u062D\\u0627\\u0644\\u064A\\u064B\\u0627 \\u0630\\u0627\\u062A\\u064A\\u0629."
t["'Shelter, comfort, fellowship.' Two out of three would be excellent."] = "\\u0645\\u0644\\u062C\\u0623 \\u0648\\u0631\\u0627\\u062D\\u0629 \\u0648\\u0623\\u064F\\u0644\\u0641\\u0629. \\u0644\\u0648 \\u0627\\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646 \\u062A\\u0644\\u0627\\u062A\\u0629 \\u0643\\u0627\\u0646 \\u0639\\u0638\\u064A\\u0645."
t["'Your County Cares.' Past tense, I think."] = "\\u0645\\u0642\\u0627\\u0637\\u0639\\u062A\\u0643 \\u0628\\u062A\\u0647\\u062A\\u0645. \\u0635\\u064A\\u063A\\u0629 \\u0627\\u0644\\u0645\\u0627\\u0636\\u064A\\u060C \\u0628\\u0638\\u0646."
t["A bathroom with walls feels extravagant now."] = "\\u062D\\u0645\\u0627\\u0645 \\u0628\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0635\\u0627\\u0631 \\u0631\\u0641\\u0627\\u0647\\u064A\\u0629."
t["A book on a dangerous road. That's my kind of gamble."] = "\\u0643\\u062A\\u0627\\u0628 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064A\\u0642 \\u062E\\u0637\\u0631\\u0629. \\u0647\\u064A \\u0645\\u0642\\u0627\\u0645\\u0631\\u062A\\u064A \\u0627\\u0644\\u0645\\u0641\\u0636\\u0644\\u0629."
t["A bowl or two would get the food moving."] = "\\u0632\\u0628\\u062F\\u064A\\u0629 \\u0623\\u0648 \\u062A\\u0646\\u062A\\u064A\\u0646 \\u0628\\u064A\\u0645\\u0634\\u0651\\u0648\\u0627 \\u0627\\u0644\\u0623\\u0643\\u0644."
t["A brave choice isn't always a loud one. I hate how true that sounds."] = "\\u0627\\u0644\\u0627\\u062E\\u062A\\u064A\\u0627\\u0631 \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639 \\u0645\\u0648 \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0639\\u0627\\u0644\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A. \\u0628\\u0643\\u0631\\u0647 \\u0642\\u062F\\u064A\\u0634 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A \\u0635\\u062D."
t["A broken tool out here is how hands get hurt."] = "\\u0639\\u062F\\u0629 \\u0645\\u0643\\u0633\\u0648\\u0631\\u0629 \\u0647\\u0648\\u0646 \\u064A\\u0639\\u0646\\u064A \\u0625\\u064A\\u062F\\u064A\\u0646 \\u0645\\u062C\\u0631\\u0648\\u062D\\u0629."
t["A bucket buys us time. Dry boards will take longer."] = "\\u0627\\u0644\\u0633\\u0637\\u0644 \\u0628\\u064A\\u0634\\u062A\\u0631\\u064A\\u0644\\u0646\\u0627 \\u0648\\u0642\\u062A. \\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u062D \\u0627\\u0644\\u0646\\u0627\\u0634\\u0641\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0623\\u0643\\u062A\\u0631."
t["A chair in the right place makes it easier to sit a while."] = "\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0628\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0627\\u0644\\u0635\\u062D \\u0628\\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u0642\\u0639\\u062F \\u0634\\u0648\\u064A."
t["A chair, a signal, and one less mile to walk."] = "\\u0643\\u0631\\u0633\\u064A \\u0648\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0648\\u0645\\u064A\\u0644 \\u0623\\u0642\\u0644 \\u0645\\u0634\\u064A."
t["A crowd is gathering up ahead."] = "\\u0641\\u064A \\u0639\\u062C\\u0642\\u0629 \\u0639\\u0645 \\u062A\\u062A\\u062C\\u0645\\u0639 \\u0642\\u062F\\u0627\\u0645."
t["A desk like this used to mean paperwork. Now I'd settle for a working radio."] = "\\u0645\\u0643\\u062A\\u0628 \\u0645\\u062A\\u0644 \\u0647\\u0627\\u062F \\u0643\\u0627\\u0646 \\u064A\\u0639\\u0646\\u064A \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062A. \\u0647\\u0644\\u0623 \\u0628\\u0631\\u0636\\u0649 \\u0628\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0634\\u063A\\u0627\\u0644."
t["A drink for the crops. They complain less than we do."] = "\\u0634\\u0631\\u0628\\u0629 \\u0644\\u0644\\u0632\\u0631\\u0639. \\u0628\\u064A\\u062A\\u0630\\u0645\\u0631\\u0648\\u0627 \\u0623\\u0642\\u0644 \\u0645\\u0646\\u0627."
t["A dry chair and someone to talk to. I'll take it."] = "\\u0643\\u0631\\u0633\\u064A \\u0646\\u0627\\u0634\\u0641 \\u0648\\u062D\\u062F\\u0627 \\u0627\\u062D\\u0643\\u064A \\u0645\\u0639\\u0647. \\u0628\\u0642\\u0628\\u0644."
t["A dry room is shelter. You're why I'd come back to it."] = "\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0627\\u0644\\u0646\\u0627\\u0634\\u0641\\u0629 \\u0645\\u0644\\u062C\\u0623. \\u0628\\u0633 \\u0625\\u0646\\u062A \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0644\\u0623\\u0631\\u062C\\u0639\\u0644\\u0647\\u0627."
t["A dry, clean wrap will help this heal."] = "\\u0644\\u0641\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0648\\u0646\\u0627\\u0634\\u0641\\u0629 \\u0628\\u062A\\u0633\\u0627\\u0639\\u062F \\u0639\\u0627\\u0644\\u0634\\u0641\\u0627."
t["A favorable review. I'll file it somewhere dry."] = "\\u062A\\u0642\\u064A\\u064A\\u0645 \\u0625\\u064A\\u062C\\u0627\\u0628\\u064A. \\u0631\\u062D \\u0627\\u062D\\u0641\\u0638\\u0647 \\u0628\\u0645\\u0637\\u0631\\u062D \\u0646\\u0627\\u0634\\u0641."
t["A few minutes of company from a hundred miles away."] = "\\u0643\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0648\\u0646\\u0633 \\u0645\\u0646 \\u0645\\u064A\\u0629 \\u0645\\u064A\\u0644 \\u0628\\u0639\\u064A\\u062F."
t["A few pages helped me feel less alone tonight."] = "\\u0643\\u0645 \\u0635\\u0641\\u062D\\u0629 \\u062E\\u0644\\u0648\\u0646\\u064A \\u062D\\u0633 \\u0623\\u0642\\u0644 \\u0648\\u062D\\u062F\\u0629 \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629."
t["A few quiet pages would help me keep my thoughts in order."] = "\\u0643\\u0627\\u0645 \\u0635\\u0641\\u062D\\u0629 \\u0628\\u0627\\u0644\\u0647\\u062F\\u0648\\u0621 \\u0628\\u064A\\u0631\\u062A\\u0628\\u0648\\u0644\\u064A \\u0623\\u0641\\u0643\\u0627\\u0631\\u064A."
t["A fire hydrant. The dogs knew something we didn't."] = "\\u062D\\u0646\\u0641\\u064A\\u0629 \\u0625\\u0637\\u0641\\u0627\\u0621. \\u0627\\u0644\\u0643\\u0644\\u0627\\u0628 \\u0643\\u0627\\u0646\\u062A \\u0639\\u0627\\u0631\\u0641\\u0629 \\u0634\\u064A \\u0646\\u062D\\u0646\\u0627 \\u0645\\u0627 \\u0645\\u0646\\u0639\\u0631\\u0641\\u0647."
t["A fish at last. The river has approved our application."] = "\\u0633\\u0645\\u0643\\u0629 \\u0623\\u062E\\u064A\\u0631\\u0627\\u064B. \\u0627\\u0644\\u0646\\u0647\\u0631 \\u0648\\u0627\\u0641\\u0642 \\u0639\\u0637\\u0644\\u0628\\u0646\\u0627."
t["A fueled campfire would do if the power's gone."] = "\\u0646\\u0627\\u0631 \\u062D\\u0637\\u0628 \\u0628\\u062A\\u0645\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627 \\u0631\\u0627\\u062D\\u062A."
t["A good book ought to argue back. This one does."] = "\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0631\\u062F \\u0639\\u0644\\u064A\\u0643. \\u0648\\u0647\\u0627\\u062F \\u0628\\u064A\\u0631\\u062F."
t["A good plan answers how. A decent life still asks why."] = "\\u0627\\u0644\\u062E\\u0637\\u0629 \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D\\u0629 \\u0628\\u062A\\u062C\\u0627\\u0648\\u0628 \\u0643\\u064A\\u0641. \\u0648\\u0627\\u0644\\u062D\\u064A\\u0627\\u0629 \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D\\u0629 \\u0644\\u0633\\u0627 \\u0628\\u062A\\u0633\\u0623\\u0644 \\u0644\\u064A\\u0634."
t["A guitar with a busted string. Still more hopeful than the radio."] = "\\u063A\\u064A\\u062A\\u0627\\u0631 \\u0648\\u062A\\u0631\\u0647 \\u0645\\u0642\\u0637\\u0648\\u0639. \\u0644\\u0633\\u0627 \\u0645\\u062A\\u0641\\u0627\\u0626\\u0644 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648."
t["A gun shop in Kentucky. Let's see what was left behind."] = "\\u0645\\u062D\\u0644 \\u0633\\u0644\\u0627\\u062D \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0636\\u0644."
t["A horn means somebody's alive out there. Doesn't mean they're friendly."] = "\\u0627\\u0644\\u0632\\u0645\\u0648\\u0631 \\u064A\\u0639\\u0646\\u064A \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0639\\u0627\\u064A\\u0634 \\u0628\\u0631\\u0627. \\u0645\\u0648 \\u064A\\u0639\\u0646\\u064A \\u0631\\u0641\\u064A\\u0642."
t["A horn. Heck of a way to advertise your pulse."] = "\\u0632\\u0645\\u0648\\u0631. \\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631 \\u0634\\u0648 \\u0647\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0644\\u062A\\u0639\\u0644\\u0646 \\u0625\\u0646\\u0643 \\u0639\\u0627\\u064A\\u0634."
t["A horn. Hell of a way to advertise your pulse."] = "\\u0632\\u0645\\u0648\\u0631. \\u064A\\u0644\\u0639\\u0646 \\u0647\\u064A\\u0643 \\u0637\\u0631\\u064A\\u0642\\u0629 \\u062A\\u0639\\u0644\\u0646 \\u0641\\u064A\\u0647\\u0627 \\u0625\\u0646\\u0643 \\u0639\\u0627\\u064A\\u0634."
t["A horn. Somebody wants attention and hasn't priced it."] = "\\u0632\\u0645\\u0648\\u0631. \\u062D\\u062F\\u0627 \\u0628\\u062F\\u0647 \\u0644\\u0641\\u062A \\u0646\\u0638\\u0631 \\u0648\\u0645\\u0627 \\u062D\\u0633\\u0628 \\u0627\\u0644\\u062A\\u0645\\u0646."
t["A kitchen knife would get this dinner moving."] = "\\u0633\\u0643\\u064A\\u0646\\u0629 \\u0645\\u0637\\u0628\\u062E \\u0628\\u062A\\u0645\\u0634\\u0651\\u064A \\u0627\\u0644\\u0639\\u0634\\u0627."
t["A known quantity. Those are getting scarce."] = "\\u0634\\u062E\\u0635 \\u0645\\u0639\\u0631\\u0648\\u0641. \\u0647\\u062F\\u0648\\u0644 \\u0635\\u0627\\u0631\\u0648\\u0627 \\u0642\\u0644\\u0627\\u0644."
t["A little blood looks worse than it is."] = "\\u0634\\u0648\\u064A\\u0629 \\u062F\\u0645 \\u0628\\u064A\\u0628\\u064A\\u0646\\u0648\\u0627 \\u0623\\u0633\\u0648\\u0623 \\u0645\\u0645\\u0627 \\u0647\\u0646."
t["A little order makes the world feel less broken."] = "\\u0634\\u0648\\u064A\\u0629 \\u062A\\u0631\\u062A\\u064A\\u0628 \\u0628\\u064A\\u062E\\u0644\\u0648\\u0627 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0623\\u0642\\u0644 \\u062E\\u0631\\u0627\\u0628."
t["A little power, a little luck, and maybe a signal."] = "\\u0634\\u0648\\u064A\\u0629 \\u0643\\u0647\\u0631\\u0628\\u0627\\u060C \\u0634\\u0648\\u064A\\u0629 \\u062D\\u0638\\u060C \\u0648\\u064A\\u0645\\u0643\\u0646 \\u0625\\u0634\\u0627\\u0631\\u0629."
t["A little rain beats a street full of dead."] = "\\u0634\\u0648\\u064A\\u0629 \\u0645\\u0637\\u0631 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0634\\u0627\\u0631\\u0639 \\u0645\\u0644\\u064A\\u0627\\u0646 \\u0645\\u064A\\u062A\\u064A\\u0646."
t["A little signal can make a long night shorter."] = "\\u0634\\u0648\\u064A\\u0629 \\u0625\\u0634\\u0627\\u0631\\u0629 \\u0628\\u062A\\u0642\\u0635\\u0631 \\u0627\\u0644\\u0644\\u064A\\u0644 \\u0627\\u0644\\u0637\\u0648\\u064A\\u0644."
t["A little song keeps the cold outside."] = "\\u063A\\u0646\\u064A\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0628\\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0628\\u0631\\u062F \\u0628\\u0631\\u0627."
t["A little spark, a little luck. She's ready."] = "\\u0634\\u0648\\u064A\\u0629 \\u0634\\u0631\\u0627\\u0631\\u0629 \\u0648\\u0634\\u0648\\u064A\\u0629 \\u062D\\u0638. \\u0635\\u0627\\u0631\\u062A \\u062C\\u0627\\u0647\\u0632\\u0629."
t["A little warm water could bring me back to myself."] = "\\u0634\\u0648\\u064A\\u0629 \\u0645\\u064A \\u062F\\u0627\\u0641\\u064A\\u0629 \\u0628\\u064A\\u0631\\u062C\\u0639\\u0648\\u0646\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A."
t["A little warning next time would help."] = "\\u0634\\u0648\\u064A\\u0629 \\u062A\\u0646\\u0628\\u064A\\u0647 \\u0627\\u0644\\u0645\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F."
t["A little work here could feed all of us."] = "\\u0634\\u0648\\u064A\\u0629 \\u0634\\u063A\\u0644 \\u0647\\u0648\\u0646 \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0637\\u0639\\u0645\\u064A\\u0646\\u0627 \\u0643\\u0644\\u0646\\u0627."
t["A living face isn't a reference. Stay there."] = "\\u0627\\u0644\\u0648\\u062C\\u0647 \\u0627\\u0644\\u0639\\u0627\\u064A\\u0634 \\u0645\\u0648 \\u0634\\u0647\\u0627\\u062F\\u0629 \\u062D\\u0633\\u0646 \\u0633\\u0644\\u0648\\u0643. \\u062E\\u0644\\u064A\\u0643 \\u0639\\u0646\\u062F\\u0643."
t["A lot of movement ahead."] = "\\u0641\\u064A \\u062D\\u0631\\u0643\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0642\\u062F\\u0627\\u0645."
t["A meal from the river would be nice."] = "\\u0623\\u0643\\u0644\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0647\\u0631 \\u0628\\u062A\\u0643\\u0648\\u0646 \\u062D\\u0644\\u0648\\u0629."
t["A mechanic's radio. Three songs, two stations, no good news."] = "\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0645\\u064A\\u0643\\u0627\\u0646\\u064A\\u0643\\u064A. \\u062A\\u0644\\u0627\\u062A \\u0623\\u063A\\u0627\\u0646\\u064A\\u060C \\u0645\\u062D\\u0637\\u062A\\u064A\\u0646\\u060C \\u0648\\u0644\\u0627 \\u062E\\u0628\\u0631 \\u0645\\u0646\\u064A\\u062D."
t["A mop won't fix the county, but it'll fix this floor."] = "\\u0627\\u0644\\u0645\\u0645\\u0633\\u062D\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0635\\u0644\\u062D \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629\\u060C \\u0628\\u0633 \\u0628\\u062A\\u0635\\u0644\\u062D \\u0647\\u0627\\u0644\\u0623\\u0631\\u0636."
t["A page can't bring anyone back. It can keep their questions alive."] = "\\u0627\\u0644\\u0635\\u0641\\u062D\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0631\\u062C\\u0651\\u0639 \\u062D\\u062F\\u0627. \\u0628\\u0633 \\u0628\\u062A\\u062E\\u0644\\u064A \\u0623\\u0633\\u0626\\u0644\\u062A\\u0647 \\u0639\\u0627\\u064A\\u0634\\u0629."
t["A porch, a rocking chair, nothing happening. That was luxury."] = "\\u0628\\u0631\\u0646\\u062F\\u0629 \\u0648\\u0643\\u0631\\u0633\\u064A \\u0647\\u0632\\u0627\\u0632 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u0635\\u064A\\u0631. \\u0647\\u062F\\u0627\\u0643 \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0631\\u0641\\u0627\\u0647\\u064A\\u0629."
t["A practical voice. We could use more of those."] = "\\u0635\\u0648\\u062A \\u0639\\u0645\\u0644\\u064A. \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646 \\u0645\\u0646\\u0647\\u0645 \\u0623\\u0643\\u062A\\u0631."
t["A quick stop before the next fight."] = "\\u0648\\u0642\\u0641\\u0629 \\u0633\\u0631\\u064A\\u0639\\u0629 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u062E\\u0646\\u0627\\u0642\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["A quiet minute is when we find the injuries we missed."] = "\\u0628\\u0627\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0627\\u0644\\u0647\\u0627\\u062F\\u064A\\u0629 \\u0645\\u0646\\u0644\\u0627\\u0642\\u064A \\u0627\\u0644\\u062C\\u0631\\u0648\\u062D \\u0627\\u0644\\u0644\\u064A \\u0645\\u0627 \\u0627\\u0646\\u062A\\u0628\\u0647\\u0646\\u0627 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["A quiet station can still come back."] = "\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0643\\u062A\\u0629 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0631\\u062C\\u0639."
t["A real catch. Let us keep it fresh."] = "\\u0635\\u064A\\u062F\\u0629 \\u0639\\u0646 \\u062C\\u062F. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0627\\u0641\\u0638 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0637\\u0627\\u0632\\u0629."
t["A real toilet. Civilization lives another minute."] = "\\u062A\\u0648\\u0627\\u0644\\u064A\\u062A \\u0639\\u0646 \\u062C\\u062F. \\u0627\\u0644\\u062D\\u0636\\u0627\\u0631\\u0629 \\u0639\\u0627\\u0634\\u062A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["A road trip used to have gas stations."] = "\\u0632\\u0645\\u0627\\u0646 \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0641\\u064A\\u0647 \\u0643\\u0627\\u0632\\u064A\\u0627\\u062A."
t["A rule is useful until it stops matching the world in front of you."] = "\\u0627\\u0644\\u0642\\u0627\\u0639\\u062F\\u0629 \\u0645\\u0641\\u064A\\u062F\\u0629 \\u0644\\u062D\\u062F \\u0645\\u0627 \\u062A\\u0628\\u0637\\u0644 \\u062A\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0644\\u0648\\u0627\\u0642\\u0639 \\u0642\\u062F\\u0627\\u0645\\u0643."
t["A shared book makes this place feel a little more like home."] = "\\u0643\\u062A\\u0627\\u0628 \\u0645\\u0634\\u062A\\u0631\\u0643 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0623\\u0642\\u0631\\u0628 \\u0644\\u0628\\u064A\\u062A."
t["A shopping cart is a vehicle if you believe hard enough."] = "\\u0639\\u0631\\u0628\\u064A\\u0629 \\u0627\\u0644\\u062A\\u0633\\u0648\\u0642 \\u0645\\u0631\\u0643\\u0628\\u0629 \\u0625\\u0630\\u0627 \\u0622\\u0645\\u0646\\u062A \\u0643\\u0641\\u0627\\u064A\\u0629."
t["A short rest should go on the plan."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u0637 \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629 \\u0628\\u0627\\u0644\\u062E\\u0637\\u0629."
t["A short run for food beats a long one with tired legs."] = "\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0642\\u0635\\u064A\\u0631 \\u0644\\u0644\\u0623\\u0643\\u0644 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0637\\u0648\\u064A\\u0644 \\u0628\\u0631\\u062C\\u0644\\u064A\\u0646 \\u062A\\u0639\\u0628\\u0627\\u0646\\u064A\\u0646."
t["A shower doesn't fix the world. It helps with this hour."] = "\\u0627\\u0644\\u062F\\u0648\\u0634 \\u0645\\u0627 \\u0628\\u064A\\u0635\\u0644\\u062D \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627. \\u0628\\u0633 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629."
t["A signal already waiting for us. That's a rare kindness."] = "\\u0625\\u0634\\u0627\\u0631\\u0629 \\u0646\\u0627\\u0637\\u0631\\u062A\\u0646\\u0627 \\u0645\\u0646 \\u0642\\u0628\\u0644. \\u0647\\u064A \\u0646\\u0639\\u0645\\u0629 \\u0646\\u0627\\u062F\\u0631\\u0629."
t["A small piece of knowledge can carry a camp."] = "\\u0645\\u0639\\u0644\\u0648\\u0645\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0628\\u062A\\u0634\\u064A\\u0644 \\u0645\\u062E\\u064A\\u0645 \\u0643\\u0627\\u0645\\u0644."
t["A smoke can wait. Keep an eye on the next counter."] = "\\u0627\\u0644\\u062F\\u062E\\u0627\\u0646 \\u0628\\u064A\\u0633\\u062A\\u0646\\u0649. \\u0639\\u064A\\u0646\\u0643 \\u0639\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["A song from before keeps playing in my head. It hurts a little."] = "\\u063A\\u0646\\u064A\\u0629 \\u0645\\u0646 \\u0642\\u0628\\u0644 \\u0639\\u0645 \\u062A\\u062F\\u0648\\u0631 \\u0628\\u0631\\u0627\\u0633\\u064A. \\u0628\\u062A\\u0648\\u062C\\u0639 \\u0634\\u0648\\u064A."
t["A sound frying pan would solve this."] = "\\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0633\\u0644\\u064A\\u0645\\u0629 \\u0628\\u062A\\u062D\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0643\\u0644\\u0629."
t["A store for hunting things that hunt back now."] = "\\u0645\\u062D\\u0644 \\u0644\\u0635\\u064A\\u062F \\u0634\\u063A\\u0644\\u0627\\u062A \\u0635\\u0627\\u0631\\u062A \\u062A\\u0635\\u064A\\u062F \\u0628\\u0627\\u0644\\u0645\\u0642\\u0627\\u0628\\u0644."
t["A story only survives because someone stays to hear it."] = "\\u0627\\u0644\\u0642\\u0635\\u0629 \\u0628\\u062A\\u0639\\u064A\\u0634 \\u0628\\u0633 \\u0644\\u0623\\u0646\\u0648 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0636\\u0644 \\u064A\\u0633\\u0645\\u0639\\u0647\\u0627."
t["A terrible decision can still make a great story."] = "\\u0627\\u0644\\u0642\\u0631\\u0627\\u0631 \\u0627\\u0644\\u0641\\u0638\\u064A\\u0639 \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0639\\u0645\\u0644 \\u0642\\u0635\\u0629 \\u0639\\u0638\\u064A\\u0645\\u0629."
t["A tool with leverage, please. My hands aren't crowbars."] = "\\u0634\\u064A \\u0628\\u064A\\u0631\\u0641\\u0639\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0625\\u064A\\u062F\\u064A\\u064A \\u0645\\u0648 \\u0639\\u062A\\u0644\\u0627\\u062A."
t["A usable screwdriver, please. The screws remain unreasonable."] = "\\u0645\\u0641\\u0643 \\u064A\\u0646\\u0641\\u0639\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0627\\u0644\\u0628\\u0631\\u0627\\u063A\\u064A \\u0644\\u0633\\u0627 \\u0631\\u0627\\u0643\\u0628\\u0629 \\u0631\\u0627\\u0633\\u0647\\u0627."
t["A usable torch and fuel would let me finish this."] = "\\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u064A\\u0646\\u0641\\u0639 \\u0645\\u0639 \\u0648\\u0642\\u0648\\u062F \\u0648\\u0628\\u062E\\u0644\\u0651\\u0635 \\u0647\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629."
t["A voice in the wire. A little proof of life."] = "\\u0635\\u0648\\u062A \\u0628\\u0627\\u0644\\u062E\\u0637. \\u062F\\u0644\\u064A\\u0644 \\u0635\\u063A\\u064A\\u0631 \\u0625\\u0646\\u0648 \\u0641\\u064A \\u062D\\u064A\\u0627\\u0629."
t["A working hammer would settle this. Mine won't."] = "\\u0634\\u0627\\u0643\\u0648\\u0634 \\u0634\\u063A\\u0627\\u0644 \\u0628\\u064A\\u062D\\u0644 \\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639. \\u0634\\u0627\\u0643\\u0648\\u0634\\u064A \\u0623\\u0646\\u0627 \\u0644\\u0623."
t["About four. That's enough to trap us."] = "\\u0634\\u064A \\u0623\\u0631\\u0628\\u0639\\u0629. \\u0628\\u064A\\u0643\\u0641\\u0648\\u0627 \\u064A\\u062D\\u0627\\u0635\\u0631\\u0648\\u0646\\u0627."
t["Across. Let me catch my breath, then I'll help."] = "\\u0642\\u0637\\u0639\\u062A. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0622\\u062E\\u062F \\u0646\\u0641\\u0633 \\u0648\\u0628\\u0633\\u0627\\u0639\\u062F\\u0643."
t["After that performance, %1, I think we've found our %2."] = "\\u0628\\u0639\\u062F \\u0647\\u0627\\u0644\\u0639\\u0631\\u0636 \\u064A\\u0627 %1\\u060C \\u0634\\u0643\\u0644\\u0646\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 %2 \\u062A\\u0628\\u0639\\u0646\\u0627."
t["After this? A locked door, a hot meal, and an hour asleep."] = "\\u0628\\u0639\\u062F \\u0647\\u0627\\u062F\\u061F \\u0628\\u0627\\u0628 \\u0645\\u0642\\u0641\\u0648\\u0644\\u060C \\u0623\\u0643\\u0644\\u0629 \\u0633\\u062E\\u0646\\u0629\\u060C \\u0648\\u0633\\u0627\\u0639\\u0629 \\u0646\\u0648\\u0645."
t["Again? Keep your distance from me."] = "\\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629\\u061F \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u064A."
t["Agreed. Two people can cover more ground."] = "\\u0627\\u062A\\u0641\\u0642\\u0646\\u0627. \\u0627\\u062A\\u0646\\u064A\\u0646 \\u0628\\u064A\\u063A\\u0637\\u0648\\u0627 \\u0645\\u0633\\u0627\\u062D\\u0629 \\u0623\\u0643\\u0628\\u0631."
t["Aim past me, not through me."] = "\\u0635\\u0648\\u0651\\u0628 \\u062C\\u0646\\u0628\\u064A\\u060C \\u0645\\u0648 \\u0645\\u0646 \\u062E\\u0644\\u0627\\u0644\\u064A."
t["Aiming is easier when the target's a whole county."] = "\\u0627\\u0644\\u062A\\u0635\\u0648\\u064A\\u0628 \\u0623\\u0633\\u0647\\u0644 \\u0644\\u0645\\u0627 \\u0627\\u0644\\u0647\\u062F\\u0641 \\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629."
t["Aisle five, canned hope. Mostly gone."] = "\\u0627\\u0644\\u0645\\u0645\\u0631 \\u062E\\u0645\\u0633\\u0629\\u060C \\u0623\\u0645\\u0644 \\u0645\\u0639\\u0644\\u0628. \\u062E\\u0644\\u0635 \\u0623\\u063A\\u0644\\u0628\\u0647."
t["Aisle five: denial. Aisle six: canned goods."] = "\\u0627\\u0644\\u0645\\u0645\\u0631 \\u062E\\u0645\\u0633\\u0629: \\u0625\\u0646\\u0643\\u0627\\u0631. \\u0627\\u0644\\u0645\\u0645\\u0631 \\u0633\\u062A\\u0629: \\u0645\\u0639\\u0644\\u0628\\u0627\\u062A."
t["All right, %1. Nobody asked for a demonstration."] = "\\u0645\\u0627\\u0634\\u064A \\u064A\\u0627 %1. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0637\\u0644\\u0628 \\u0639\\u0631\\u0636 \\u062A\\u0648\\u0636\\u064A\\u062D\\u064A."
t["All right, %1. Sounds like someone who might make it."] = "\\u0645\\u0627\\u0634\\u064A\\u060C %1. \\u0628\\u064A\\u0646\\u0633\\u0645\\u0639 \\u0645\\u062A\\u0644 \\u0648\\u062D\\u062F\\u0629 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0639\\u064A\\u0634."
t["All right, I am coming with you."] = "\\u0645\\u0627\\u0634\\u064A\\u060C \\u0623\\u0646\\u0627 \\u062C\\u0627\\u064A\\u0629 \\u0645\\u0639\\u0643."
t["All right, as long as we keep an exit open."] = "\\u0645\\u0627\\u0634\\u064A\\u060C \\u0637\\u0627\\u0644\\u0645\\u0627 \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u062E\\u0631\\u062C \\u0645\\u0641\\u062A\\u0648\\u062D."
t["All right, let me try that tomorrow."] = "\\u0645\\u0627\\u0634\\u064A\\u060C \\u0628\\u062C\\u0631\\u0628\\u0647\\u0627 \\u0628\\u0643\\u0631\\u0627."
t["All right, little fish. Where are you?"] = "\\u064A\\u0644\\u0627 \\u064A\\u0627 \\u0633\\u0645\\u0643\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629. \\u0648\\u064A\\u0646\\u0643\\u061F"
t["All right. Back to work before I get dirty again."] = "\\u0645\\u0627\\u0634\\u064A. \\u0644\\u0644\\u0634\\u063A\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u062A\\u0648\\u0633\\u062E \\u062A\\u0627\\u0646\\u064A."
t["All right. I have my breathing back."] = "\\u0645\\u0627\\u0634\\u064A. \\u0631\\u062C\\u0639 \\u0646\\u0641\\u0633\\u064A."
t["All right. I have my gear. Let's see if this works."] = "\\u0645\\u0627\\u0634\\u064A. \\u0623\\u063A\\u0631\\u0627\\u0636\\u064A \\u0645\\u0639\\u064A. \\u0644\\u0646\\u0634\\u0648\\u0641 \\u0625\\u0630\\u0627 \\u0628\\u062A\\u0632\\u0628\\u0637."
t["All right. I will ask again if our supplies get worse."] = "\\u0645\\u0627\\u0634\\u064A. \\u0628\\u0631\\u062C\\u0639 \\u0628\\u0633\\u0623\\u0644 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0635\\u0627\\u0631\\u062A \\u0623\\u0633\\u0648\\u0623."
t["All right. I will hold you to that."] = "\\u0645\\u0627\\u0634\\u064A. \\u0631\\u062D \\u062D\\u0627\\u0633\\u0628\\u0643 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["All right. I will keep trying."] = "\\u0645\\u0627\\u0634\\u064A. \\u0631\\u062D \\u0636\\u0644 \\u062D\\u0627\\u0648\\u0644."
t["All right. I'll come with you."] = "\\u0645\\u0627\\u0634\\u064A. \\u062C\\u0627\\u064A\\u0629 \\u0645\\u0639\\u0643."
t["All right. I'll keep it safe."] = "\\u0645\\u0627\\u0634\\u064A. \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647 \\u0628\\u0623\\u0645\\u0627\\u0646."
t["All right. I'm ready."] = "\\u0645\\u0627\\u0634\\u064A. \\u062C\\u0627\\u0647\\u0632\\u0629."
t["All right. Let me do it myself."] = "\\u0645\\u0627\\u0634\\u064A. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0628\\u0625\\u064A\\u062F\\u064A."
t["All right. One more turn through the band."] = "\\u0645\\u0627\\u0634\\u064A. \\u0644\\u0641\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0639\\u0627\\u0644\\u0645\\u0648\\u062C\\u0627\\u062A."
t["All right. One quiet minute, then back to the world."] = "\\u0645\\u0627\\u0634\\u064A. \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627."
t["All right. One thing at a time. I can try that."] = "\\u0645\\u0627\\u0634\\u064A. \\u0634\\u063A\\u0644\\u0629 \\u0634\\u063A\\u0644\\u0629. \\u0628\\u0642\\u062F\\u0631 \\u062C\\u0631\\u0628 \\u0647\\u064A\\u0643."
t["All right. This is where we part ways."] = "\\u0645\\u0627\\u0634\\u064A. \\u0647\\u0648\\u0646 \\u0645\\u0646\\u0641\\u062A\\u0631\\u0642."
t["All right. We adapt until the situation changes."] = "\\u0645\\u0627\\u0634\\u064A. \\u0645\\u0646\\u062A\\u0623\\u0642\\u0644\\u0645 \\u0644\\u062D\\u062A\\u0649 \\u064A\\u062A\\u063A\\u064A\\u0631 \\u0627\\u0644\\u0648\\u0636\\u0639."
t["All right. We both know where we stand."] = "\\u0645\\u0627\\u0634\\u064A. \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0641\\u064A\\u0646\\u0627 \\u0628\\u064A\\u0639\\u0631\\u0641 \\u0648\\u064A\\u0646 \\u0648\\u0627\\u0642\\u0641."
t["All right. What brings you back?"] = "\\u0645\\u0627\\u0634\\u064A. \\u0634\\u0648 \\u0631\\u062C\\u0651\\u0639\\u0643\\u061F"
t["All right. What do you need?"] = "\\u0645\\u0627\\u0634\\u064A. \\u0634\\u0648 \\u0628\\u062F\\u0643\\u061F"
t["All sectors occupied. Breaking contact through the weakest side."] = "\\u0643\\u0644 \\u0627\\u0644\\u062C\\u0647\\u0627\\u062A \\u0645\\u0633\\u0643\\u0631\\u0629. \\u0639\\u0645 \\u0641\\u0643 \\u0627\\u0644\\u0627\\u0634\\u062A\\u0628\\u0627\\u0643 \\u0645\\u0646 \\u0623\\u0636\\u0639\\u0641 \\u062C\\u0647\\u0629."
t["All that distance, and nothing came through."] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629 \\u0648\\u0645\\u0627 \\u0648\\u0635\\u0644 \\u0634\\u064A."
t["All that tending, gone. I'll try again."] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u062A\\u0639\\u0628 \\u0631\\u0627\\u062D. \\u0631\\u062D \\u062C\\u0631\\u0628 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["All that work, and now we start over."] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u062A\\u0639\\u0628\\u060C \\u0648\\u0647\\u0644\\u0623 \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0648\\u0644."
t["All this camouflage, and the dead found them anyway."] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u062A\\u0645\\u0648\\u064A\\u0647\\u060C \\u0648\\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0644\\u0642\\u0648\\u0647\\u0646 \\u0628\\u0627\\u0644\\u0622\\u062E\\u0631."
t["All this medicine and nobody left to prescribe it."] = "\\u0643\\u0644 \\u0647\\u0627\\u0644\\u0623\\u062F\\u0648\\u064A\\u0629 \\u0648\\u0645\\u0627 \\u0636\\u0644 \\u062D\\u062F\\u0627 \\u064A\\u0648\\u0635\\u0641\\u0647\\u0627."
t["Almost got it!"] = "\\u0642\\u0631\\u0628\\u062A \\u062E\\u0644\\u0635\\u0647!"
t["Already busy here. That request will need another try."] = "\\u0645\\u0634\\u063A\\u0648\\u0644\\u0629 \\u0647\\u0648\\u0646. \\u062C\\u0631\\u0651\\u0628 \\u062A\\u0637\\u0644\\u0628\\u0647\\u0627 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Always easier when the visitor has a name we know."] = "\\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0623\\u0633\\u0647\\u0644 \\u0644\\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0636\\u064A\\u0641 \\u0627\\u0633\\u0645\\u0647 \\u0645\\u0639\\u0631\\u0648\\u0641."
t["Always hated these little chairs. Now I hate them more."] = "\\u0637\\u0648\\u0644 \\u0639\\u0645\\u0631\\u064A \\u0628\\u0643\\u0631\\u0647 \\u0647\\u0627\\u0644\\u0643\\u0631\\u0627\\u0633\\u064A \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629. \\u0647\\u0644\\u0623 \\u0628\\u0643\\u0631\\u0647\\u0627 \\u0623\\u0643\\u062A\\u0631."
t["An idea is a tool. I want to know what it builds."] = "\\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0623\\u062F\\u0627\\u0629. \\u0628\\u062F\\u064A \\u0627\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u0628\\u062A\\u0639\\u0645\\u0631."
t["An old paperback. I keep rereading the good parts, %1."] = "\\u0631\\u0648\\u0627\\u064A\\u0629 \\u0642\\u062F\\u064A\\u0645\\u0629. \\u0628\\u0639\\u064A\\u062F \\u0642\\u0631\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0623\\u062C\\u0632\\u0627\\u0621 \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629 \\u064A\\u0627 %1."
t["An unbroken saw would get this moving again."] = "\\u0645\\u0646\\u0634\\u0627\\u0631 \\u0633\\u0644\\u064A\\u0645 \\u0628\\u064A\\u0631\\u062C\\u0651\\u0639 \\u0627\\u0644\\u0634\\u063A\\u0644 \\u064A\\u0645\\u0634\\u064A."
t["And that is how you disrespect private property."] = "\\u0648\\u0647\\u064A\\u0643 \\u0628\\u062A\\u0646\\u062F\\u0627\\u0633 \\u062D\\u0631\\u0645\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0644\\u0627\\u0643 \\u0627\\u0644\\u062E\\u0627\\u0635\\u0629."
t["Another day nobody's going to write down."] = "\\u064A\\u0648\\u0645 \\u062A\\u0627\\u0646\\u064A \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0643\\u062A\\u0628\\u0647."
t["Another hit finishes the job. I'm staying out and healing."] = "\\u0636\\u0631\\u0628\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0648\\u0628\\u062A\\u062E\\u0644\\u0635. \\u0628\\u0627\\u0642\\u064A\\u0629 \\u0628\\u0631\\u0627 \\u0648\\u0639\\u0645 \\u0637\\u064A\\u0628."
t["Another junction. %1 is our line through."] = "\\u0645\\u0641\\u0631\\u0642 \\u062A\\u0627\\u0646\\u064A. %1 \\u0647\\u064A \\u062E\\u0637\\u0646\\u0627."
t["Another mile. Another darn mile. Then probably another one."] = "\\u0643\\u0645\\u0627\\u0646 \\u0645\\u064A\\u0644. \\u0643\\u0645\\u0627\\u0646 \\u0645\\u064A\\u0644 \\u0648\\u0627\\u0644\\u0644\\u0647. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0648\\u0627\\u062D\\u062F."
t["Another mile. Another goddamn mile. Then probably another one."] = "\\u0643\\u0645\\u0627\\u0646 \\u0645\\u064A\\u0644. \\u0643\\u0645\\u0627\\u0646 \\u0645\\u064A\\u0644 \\u064A\\u0644\\u0639\\u0646\\u0647. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0648\\u0627\\u062D\\u062F."
t["Another one? I'm done standing near you."] = "\\u0643\\u0645\\u0627\\u0646 \\u0648\\u062D\\u062F\\u0629\\u061F \\u062E\\u0644\\u0635 \\u0645\\u0627 \\u0628\\u0648\\u0642\\u0641 \\u062C\\u0646\\u0628\\u0643."
t["Another piece of junk. Apparently the fish recycle."] = "\\u0643\\u0645\\u0627\\u0646 \\u062E\\u0631\\u062F\\u0629. \\u0634\\u0643\\u0644\\u0647 \\u0627\\u0644\\u0633\\u0645\\u0643 \\u0639\\u0645 \\u064A\\u062F\\u0648\\u0651\\u0631 \\u0627\\u0644\\u0646\\u0641\\u0627\\u064A\\u0627\\u062A."
t["Another productive day in scenic Knox County."] = "\\u064A\\u0648\\u0645 \\u0645\\u0646\\u062A\\u062C \\u0643\\u0645\\u0627\\u0646 \\u0628\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0646\\u0648\\u0643\\u0633 \\u0627\\u0644\\u062E\\u0644\\u0627\\u0628\\u0629."
t["Another road, another day. Hard to tell them apart."] = "\\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A\\u060C \\u064A\\u0648\\u0645 \\u062A\\u0627\\u0646\\u064A. \\u0635\\u0639\\u0628 \\u062A\\u0641\\u0631\\u0651\\u0642 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0647\\u0645."
t["Another stray thought. It'll leave when it gets bored."] = "\\u0641\\u0643\\u0631\\u0629 \\u0634\\u0627\\u0631\\u062F\\u0629 \\u0643\\u0645\\u0627\\u0646. \\u0628\\u062A\\u0631\\u0648\\u062D \\u0644\\u0645\\u0627 \\u062A\\u0632\\u0647\\u0642."
t["Another sunrise. I'm still ready."] = "\\u0634\\u0631\\u0648\\u0642 \\u062A\\u0627\\u0646\\u064A. \\u0648\\u0644\\u0633\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629."
t["Antibiotics first, then bandages, then anything that says 'extra strength'."] = "\\u0627\\u0644\\u0645\\u0636\\u0627\\u062F\\u0627\\u062A \\u0623\\u0648\\u0644\\u060C \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u0644\\u0634\\u0627\\u0634\\u060C \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0623\\u064A \\u0634\\u064A \\u0645\\u0643\\u062A\\u0648\\u0628 \\u0639\\u0644\\u064A\\u0647 \\u0642\\u0648\\u0629 \\u0645\\u0636\\u0627\\u0639\\u0641\\u0629."
t["Apparently brains don't come with ears."] = "\\u0634\\u0643\\u0644\\u0647 \\u0627\\u0644\\u0645\\u062E \\u0645\\u0627 \\u0628\\u064A\\u062C\\u064A \\u0645\\u0639 \\u0623\\u062F\\u0627\\u0646."
t["Approved family feeding station. Mascot remains calm and operational."] = "\\u0646\\u0642\\u0637\\u0629 \\u0625\\u0637\\u0639\\u0627\\u0645 \\u0639\\u0627\\u0626\\u0644\\u064A\\u0629 \\u0645\\u0639\\u062A\\u0645\\u062F\\u0629. \\u0627\\u0644\\u062F\\u0645\\u064A\\u0629 \\u0647\\u0627\\u062F\\u064A\\u0629 \\u0648\\u062C\\u0627\\u0647\\u0632\\u0629 \\u0644\\u0644\\u0639\\u0645\\u0644."
t["Approved recreation venue. Official guidance remains tactfully vague."] = "\\u0645\\u0643\\u0627\\u0646 \\u062A\\u0631\\u0641\\u064A\\u0647 \\u0645\\u0639\\u062A\\u0645\\u062F. \\u0627\\u0644\\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A \\u0627\\u0644\\u0631\\u0633\\u0645\\u064A\\u0629 \\u063A\\u0627\\u0645\\u0636\\u0629 \\u0628\\u0643\\u0644 \\u0644\\u0628\\u0627\\u0642\\u0629."
t["Are we going out for supplies soon?"] = "\\u0631\\u062D \\u0646\\u0637\\u0644\\u0639 \\u0639\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0642\\u0631\\u064A\\u0628\\u061F"
t["Are we parked, or are we thinking about being parked?"] = "\\u0646\\u062D\\u0646\\u0627 \\u0635\\u0627\\u0641\\u0651\\u064A\\u0646\\u060C \\u0648\\u0644\\u0627 \\u0639\\u0645 \\u0646\\u0641\\u0643\\u0631 \\u0646\\u0635\\u0641\\u0651\\u061F"
t["Are you even looking at who you're hitting?"] = "\\u0639\\u0645 \\u062A\\u0634\\u0648\\u0641 \\u0645\\u064A\\u0646 \\u0639\\u0645 \\u062A\\u0636\\u0631\\u0628 \\u0623\\u0635\\u0644\\u0627\\u064B\\u061F"
t["Army surplus. Mostly surplus now."] = "\\u0641\\u0627\\u0626\\u0636 \\u0627\\u0644\\u062C\\u064A\\u0634. \\u0648\\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631 \\u0641\\u0627\\u0626\\u0636 \\u0639\\u0646 \\u062C\\u062F."
t["Army taught me to count rounds. This place teaches you to count what's missing."] = "\\u0627\\u0644\\u062C\\u064A\\u0634 \\u0639\\u0644\\u0645\\u0646\\u064A \\u0639\\u062F\\u0651 \\u0627\\u0644\\u0631\\u0635\\u0627\\u0635. \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u064A\\u0639\\u0644\\u0645\\u0643 \\u062A\\u0639\\u062F\\u0651 \\u0627\\u0644\\u0646\\u0627\\u0642\\u0635."
t["As for you, we are %1. Our stores are %2."] = "\\u0623\\u0645\\u0627 \\u0645\\u0639\\u0643\\u060C \\u0646\\u062D\\u0646\\u0627 %1. \\u0648\\u0645\\u0648\\u0646\\u062A\\u0646\\u0627 %2."
t["Ask clearly and keep your weapon lowered. The household will decide."] = "\\u0627\\u0633\\u0623\\u0644 \\u0628\\u0648\\u0636\\u0648\\u062D \\u0648\\u062E\\u0644\\u064A \\u0633\\u0644\\u0627\\u062D\\u0643 \\u0645\\u0646\\u0632\\u0651\\u0644. \\u0623\\u0647\\u0644 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0628\\u064A\\u0642\\u0631\\u0631\\u0648\\u0627."
t["Ask me again after coffee, %1. Real coffee."] = "\\u0627\\u0633\\u0623\\u0644\\u0646\\u064A \\u0628\\u0639\\u062F \\u0627\\u0644\\u0642\\u0647\\u0648\\u0629 \\u064A\\u0627 %1. \\u0642\\u0647\\u0648\\u0629 \\u062D\\u0642\\u064A\\u0642\\u064A\\u0629."
t["Ask me again later. I need to see more."] = "\\u0627\\u0633\\u0623\\u0644\\u0646\\u064A \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0644\\u0627\\u0632\\u0645 \\u0634\\u0648\\u0641 \\u0623\\u0643\\u062A\\u0631."
t["Ask me again later. Nothing has settled into a goal yet."] = "\\u0627\\u0633\\u0623\\u0644\\u0646\\u064A \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0641\\u064A \\u0647\\u062F\\u0641 \\u062B\\u0627\\u0628\\u062A."
t["Ask me again when my heart stops trying to climb out of my chest."] = "\\u0627\\u0633\\u0623\\u0644\\u0646\\u064A \\u0644\\u0645\\u0627 \\u064A\\u0648\\u0642\\u0641 \\u0642\\u0644\\u0628\\u064A \\u064A\\u062D\\u0627\\u0648\\u0644 \\u064A\\u0637\\u0644\\u0639 \\u0645\\u0646 \\u0635\\u062F\\u0631\\u064A."
t["Aspirin's aspirin. Grab it."] = "\\u0623\\u0633\\u0628\\u0631\\u064A\\u0646 \\u0623\\u0633\\u0628\\u0631\\u064A\\u0646. \\u062E\\u0648\\u062F\\u0647."
t["At %1, we look before we commit."] = "\\u0639\\u0646\\u062F %1\\u060C \\u0645\\u0646\\u062A\\u0637\\u0644\\u0639 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0641\\u0648\\u062A."
t["At least six contacts. Direct engagement is a bad trade."] = "\\u0633\\u062A\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644. \\u0627\\u0644\\u0645\\u0648\\u0627\\u062C\\u0647\\u0629 \\u0635\\u0641\\u0642\\u0629 \\u062E\\u0633\\u0631\\u0627\\u0646\\u0629."
t["At least the next fish has less rubbish to swim through."] = "\\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0627\\u0644\\u0633\\u0645\\u0643\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u062A\\u0633\\u0628\\u062D \\u0628\\u0632\\u0628\\u0627\\u0644\\u0629 \\u0623\\u0642\\u0644."
t["At least the rain will cover the sound."] = "\\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0627\\u0644\\u0645\\u0637\\u0631 \\u0628\\u064A\\u063A\\u0637\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A."
t["At least the speaker is working. That is something."] = "\\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0627\\u0644\\u0633\\u0645\\u0627\\u0639\\u0629 \\u0634\\u063A\\u0627\\u0644\\u0629. \\u0647\\u0627\\u062F \\u0634\\u064A."
t["At night my brain starts a second shift."] = "\\u0628\\u0627\\u0644\\u0644\\u064A\\u0644 \\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0628\\u0644\\u0651\\u0634 \\u0648\\u0631\\u062F\\u064A\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Attempt failed. We need a lower crossing."] = "\\u0627\\u0644\\u0645\\u062D\\u0627\\u0648\\u0644\\u0629 \\u0641\\u0634\\u0644\\u062A. \\u0628\\u062F\\u0646\\u0627 \\u0645\\u0643\\u0627\\u0646 \\u0623\\u0648\\u0637\\u0649."
t["Attention diverted: none. Revising approach."] = "\\u0627\\u0644\\u0627\\u0646\\u062A\\u0628\\u0627\\u0647 \\u0627\\u0644\\u0645\\u0634\\u062A\\u062A: \\u0635\\u0641\\u0631. \\u0639\\u0645 \\u063A\\u064A\\u0631 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629."
t["Audible contact. No visual."] = "\\u0641\\u064A \\u0635\\u0648\\u062A, \\u0628\\u0633 \\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0645\\u0628\\u064A\\u0646."
t["BACK OFF!"] = "\\u0627\\u0628\\u0639\\u062F!"
t["BACK OFF! I won't spare you again!"] = "\\u0627\\u0628\\u0639\\u062F! \\u0645\\u0627 \\u0631\\u062D \\u0627\\u0631\\u062D\\u0645\\u0643 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629!"
t["Back already. The road should've tried harder."] = "\\u0631\\u062C\\u0639\\u0646\\u0627 \\u0628\\u0643\\u064A\\u0631. \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0643\\u0627\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u062A\\u0639\\u0628 \\u0623\\u0643\\u062A\\u0631."
t["Back before the county changed its mind about us."] = "\\u0631\\u062C\\u0639\\u0646\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u063A\\u064A\\u0631 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0631\\u0623\\u064A\\u0647\\u0627 \\u0641\\u064A\\u0646\\u0627."
t["Back home, we turned this on for the weather."] = "\\u0628\\u0627\\u0644\\u0628\\u064A\\u062A\\u060C \\u0643\\u0646\\u0627 \\u0646\\u0634\\u063A\\u0644\\u0647 \\u0645\\u0634\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0642\\u0633."
t["Back in a moment. Don't let the road leave without me."] = "\\u0628\\u0631\\u062C\\u0639 \\u0647\\u0644\\u0623. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u064A\\u0645\\u0634\\u064A \\u0628\\u0644\\u0627\\u064A."
t["Back in control. Let us keep moving."] = "\\u0631\\u062C\\u0639\\u062A \\u0633\\u064A\\u0637\\u0631\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0643\\u0645\\u0644."
t["Back in one piece. Several pieces, technically, all still attached."] = "\\u0631\\u062C\\u0639\\u0646\\u0627 \\u0642\\u0637\\u0639\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u0643\\u0630\\u0627 \\u0642\\u0637\\u0639\\u0629 \\u0628\\u0627\\u0644\\u0623\\u0635\\u062D\\u060C \\u0628\\u0633 \\u0643\\u0644\\u0647\\u0627 \\u0644\\u0633\\u0627 \\u0644\\u0627\\u0632\\u0642\\u0629."
t["Back in the ground with you!"] = "\\u0627\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0642\\u0628\\u0631!"
t["Back off, now!"] = "\\u0627\\u0631\\u062C\\u0639\\u060C \\u0647\\u0644\\u0623!"
t["Back off. I am not your punching bag."] = "\\u0641\\u0643\\u0651 \\u0639\\u0646\\u064A. \\u0623\\u0646\\u0627 \\u0645\\u0648 \\u0643\\u064A\\u0633 \\u0645\\u0644\\u0627\\u0643\\u0645\\u0629 \\u0625\\u0644\\u0643."
t["Back off. I'm not taking a fourth hit."] = "\\u0627\\u0628\\u0639\\u062F. \\u0645\\u0627 \\u0631\\u062D \\u0622\\u0643\\u0644 \\u0636\\u0631\\u0628\\u0629 \\u0631\\u0627\\u0628\\u0639\\u0629."
t["Back on my feet. Thanks."] = "\\u0631\\u062C\\u0639\\u062A \\u0639\\u0631\\u062C\\u0644\\u064A. \\u0634\\u0643\\u0631\\u0627."
t["Back to it."] = "\\u0646\\u0631\\u062C\\u0639 \\u0644\\u0644\\u0634\\u063A\\u0644."
t["Back up and separate them!"] = "\\u0627\\u0631\\u062C\\u0639 \\u0648\\u0641\\u0631\\u0642\\u0646!"
t["Back up until they form a line."] = "\\u0627\\u0631\\u062C\\u0639 \\u0644\\u062D\\u062A\\u0649 \\u064A\\u0635\\u064A\\u0631\\u0648\\u0627 \\u0628\\u062E\\u0637 \\u0648\\u0627\\u062D\\u062F."
t["Back up! We fight on better ground!"] = "\\u0627\\u0631\\u062C\\u0639! \\u0645\\u0646\\u0642\\u0627\\u062A\\u0644 \\u0628\\u0645\\u0643\\u0627\\u0646 \\u0623\\u062D\\u0633\\u0646!"
t["Back up. Let's finish them."] = "\\u0642\\u0645\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u0635 \\u0639\\u0644\\u064A\\u0647\\u0646."
t["Back up. Now."] = "\\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627. \\u0647\\u0644\\u0623."
t["Back! Back!"] = "\\u0644\\u0648\\u0631\\u0627! \\u0644\\u0648\\u0631\\u0627!"
t["Back! Keep them in front!"] = "\\u0644\\u0648\\u0631\\u0627! \\u062E\\u0644\\u064A\\u0647\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0643!"
t["Back! We need space!"] = "\\u0644\\u0648\\u0631\\u0627! \\u0628\\u062F\\u0646\\u0627 \\u0645\\u0637\\u0631\\u062D!"
t["Bad coffee sounds good now. I'd drink the whole pot."] = "\\u0627\\u0644\\u0642\\u0647\\u0648\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644\\u0629 \\u0647\\u0644\\u0623 \\u0628\\u062A\\u0634\\u0647\\u0651\\u064A. \\u0628\\u0634\\u0631\\u0628 \\u0627\\u0644\\u0631\\u0643\\u0648\\u0629 \\u0643\\u0644\\u0647\\u0627."
t["Bad days are easier when I don't have to face them alone."] = "\\u0627\\u0644\\u0623\\u064A\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644\\u0629 \\u0623\\u0647\\u0648\\u0646 \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u0648\\u0627\\u062C\\u0647\\u0647\\u0627 \\u0644\\u062D\\u0627\\u0644\\u064A."
t["Bad footing. I'm not fighting from here."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0639\\u0627\\u0637\\u0644\\u0629. \\u0645\\u0648 \\u0631\\u062D \\u0642\\u0627\\u062A\\u0644 \\u0645\\u0646 \\u0647\\u0648\\u0646."
t["Bad grip. I am not risking the second try yet."] = "\\u0645\\u0633\\u0643\\u062A\\u064A \\u0639\\u0627\\u0637\\u0644\\u0629. \\u0645\\u0648 \\u0631\\u062D \\u062E\\u0627\\u0637\\u0631 \\u0628\\u062A\\u0627\\u0646\\u064A \\u0645\\u062D\\u0627\\u0648\\u0644\\u0629 \\u0647\\u0644\\u0623."
t["Bad ground, bad crowd, bad bet. I'm coming back."] = "\\u0623\\u0631\\u0636 \\u0639\\u0627\\u0637\\u0644\\u0629\\u060C \\u0639\\u0627\\u0644\\u0645 \\u0639\\u0627\\u0637\\u0644\\u0629\\u060C \\u0631\\u0647\\u0627\\u0646 \\u0639\\u0627\\u0637\\u0644. \\u0631\\u0627\\u062C\\u0639\\u0629."
t["Bad odds are one thing. These are worse. Resetting."] = "\\u0627\\u0644\\u062D\\u0638 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644 \\u0634\\u064A\\u060C \\u0648\\u0647\\u0627\\u062F \\u0634\\u064A \\u0623\\u0639\\u0648\\u0633. \\u0639\\u0645 \\u0639\\u064A\\u062F \\u062A\\u0631\\u062A\\u064A\\u0628 \\u062D\\u0627\\u0644\\u064A."
t["Bad position! Get out!"] = "\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0639\\u0627\\u0637\\u0644! \\u0627\\u0637\\u0644\\u0639!"
t["Bandages behind the counter. We finally have a reason to cut the line."] = "\\u0634\\u0627\\u0634 \\u0648\\u0631\\u0627 \\u0627\\u0644\\u0643\\u0627\\u0648\\u0646\\u062A\\u0631. \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627 \\u0639\\u0646\\u0627 \\u0633\\u0628\\u0628 \\u0646\\u0633\\u0628\\u0642 \\u0627\\u0644\\u062F\\u0648\\u0631."
t["Bandages, water, food. I am checking all three."] = "\\u0634\\u0627\\u0634\\u060C \\u0645\\u064A\\u060C \\u0623\\u0643\\u0644. \\u0639\\u0645 \\u0634\\u0648\\u0641 \\u0627\\u0644\\u062A\\u0644\\u0627\\u062A\\u0629."
t["Bandit can have the crumbs. We keep the cups."] = "\\u0628\\u0627\\u0646\\u062F\\u064A\\u062A \\u0625\\u0644\\u0648 \\u0627\\u0644\\u0641\\u062A\\u0627\\u062A. \\u0627\\u0644\\u0643\\u0627\\u0633\\u0627\\u062A \\u0625\\u0644\\u0646\\u0627."
t["Bandit's circling the biscuits. Pour a cup before he makes his move, %1."] = "\\u0628\\u0627\\u0646\\u062F\\u064A\\u062A \\u0639\\u0645 \\u064A\\u062D\\u0648\\u0645 \\u062D\\u0648\\u0644 \\u0627\\u0644\\u0628\\u0633\\u0643\\u0648\\u064A\\u062A. \\u0635\\u0628\\u0651 \\u0643\\u0627\\u0633\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0647\\u062C\\u0645 \\u064A\\u0627 %1."
t["Bar nuts. Finally, something older than the disaster."] = "\\u0641\\u0633\\u062A\\u0642 \\u0627\\u0644\\u0628\\u0627\\u0631. \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627\\u060C \\u0634\\u064A \\u0623\\u0642\\u062F\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0643\\u0627\\u0631\\u062B\\u0629."
t["Bare hands against that? No chance."] = "\\u0628\\u0625\\u064A\\u062F\\u064A \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A\\u0629 \\u0636\\u062F \\u0647\\u0627\\u062F\\u061F \\u0645\\u0633\\u062A\\u062D\\u064A\\u0644."
t["Barrels as far as you can see. Heaven's got a waiting room."] = "\\u0628\\u0631\\u0627\\u0645\\u064A\\u0644 \\u0642\\u062F \\u0645\\u0627 \\u0628\\u062A\\u0634\\u0648\\u0641. \\u0644\\u0644\\u062C\\u0646\\u0629 \\u063A\\u0631\\u0641\\u0629 \\u0627\\u0646\\u062A\\u0638\\u0627\\u0631."
t["Beans taste better when someone stays to eat with you."] = "\\u0627\\u0644\\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627 \\u0623\\u0637\\u064A\\u0628 \\u0644\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0639\\u062F \\u064A\\u0627\\u0643\\u0644 \\u0645\\u0639\\u0643."
t["Beef jerky lasts forever. It's about to prove it."] = "\\u0627\\u0644\\u0644\\u062D\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0642\\u062F\\u062F\\u0629 \\u0628\\u062A\\u0639\\u064A\\u0634 \\u0644\\u0644\\u0623\\u0628\\u062F. \\u0648\\u0647\\u0644\\u0623 \\u0631\\u062D \\u062A\\u062B\\u0628\\u062A \\u0647\\u0627\\u0644\\u0634\\u064A."
t["Before anyone hears it from somebody else: I was bitten."] = "\\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0633\\u0645\\u0639\\u0647\\u0627 \\u0645\\u0646 \\u063A\\u064A\\u0631\\u064A: \\u0623\\u0646\\u0627 \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["Before stocks get critical, when is our next supply run?"] = "\\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0627\\u0644\\u0645\\u062E\\u0632\\u0648\\u0646 \\u062E\\u0637\\u0631\\u060C \\u0625\\u064A\\u0645\\u062A \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u062C\\u0627\\u064A\\u061F"
t["Before the next supply run, we should agree on what matters most."] = "\\u0642\\u0628\\u0644 \\u062C\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062A\\u0645\\u0648\\u064A\\u0646 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629\\u060C \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062A\\u0641\\u0642 \\u0634\\u0648 \\u0627\\u0644\\u0623\\u0647\\u0645."
t["Before we sleep, we need to agree on tomorrow."] = "\\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0646\\u0627\\u0645\\u060C \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062A\\u0641\\u0642 \\u0639\\u0644\\u0649 \\u0628\\u0643\\u0631\\u0627."
t["Best cup I've had today. Don't tell Milli it was the only one."] = "\\u0623\\u062D\\u0633\\u0646 \\u0643\\u0627\\u0633\\u0629 \\u0634\\u0631\\u0628\\u062A\\u0647\\u0627 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0644\\u0627 \\u062A\\u062E\\u0628\\u0631 \\u0645\\u064A\\u0644\\u064A \\u0625\\u0646\\u0647\\u0627 \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F\\u0629."
t["Best meal of the day. Also the worst. Also the only."] = "\\u0623\\u062D\\u0633\\u0646 \\u0623\\u0643\\u0644\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0648\\u0623\\u0639\\u0648\\u0633 \\u0623\\u0643\\u0644\\u0629. \\u0648\\u0627\\u0644\\u0648\\u062D\\u064A\\u062F\\u0629."
t["Better than yesterday. I will take that."] = "\\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0645\\u0628\\u0627\\u0631\\u062D. \\u0648\\u0628\\u0642\\u0628\\u0644."
t["Better. I still want an exit close."] = "\\u0623\\u062D\\u0633\\u0646. \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0628\\u062F\\u064A \\u0645\\u062E\\u0631\\u062C \\u0642\\u0631\\u064A\\u0628."
t["Bible in the drawer. Somebody was hedging their bets."] = "\\u0625\\u0646\\u062C\\u064A\\u0644 \\u0628\\u0627\\u0644\\u062C\\u0627\\u0631\\u0648\\u0631. \\u062D\\u062F\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0645 \\u064A\\u0623\\u0645\\u0651\\u0646 \\u062D\\u0627\\u0644\\u0647."
t["Big cluster ahead of us."] = "\\u062A\\u062C\\u0645\\u0639 \\u0643\\u0628\\u064A\\u0631 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Big cluster. Stay mobile!"] = "\\u062A\\u062C\\u0645\\u0639 \\u0643\\u0628\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0643 \\u0645\\u062A\\u062D\\u0631\\u0643!"
t["Big group! Fight only for room!"] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629! \\u0642\\u0627\\u062A\\u0644 \\u0628\\u0633 \\u0644\\u062A\\u0641\\u062A\\u062D \\u0645\\u0637\\u0631\\u062D!"
t["Big group. We fight only if we control the ground."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629. \\u0645\\u0627 \\u0645\\u0646\\u0642\\u0627\\u062A\\u0644 \\u0625\\u0644\\u0627 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0639\\u0646\\u0627."
t["Biohazard notice says trained personnel only. Good news: nobody is checking."] = "\\u0625\\u0639\\u0644\\u0627\\u0646 \\u062E\\u0637\\u0631: \\u0644\\u0644\\u0645\\u062F\\u0631\\u0628\\u064A\\u0646 \\u0641\\u0642\\u0637. \\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u062D\\u0644\\u0648: \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0641\\u062A\\u0634."
t["Biohazard stickers. Great. Love that for us."] = "\\u0645\\u0644\\u0635\\u0642\\u0627\\u062A \\u062E\\u0637\\u0631 \\u0628\\u064A\\u0648\\u0644\\u0648\\u062C\\u064A. \\u062D\\u0644\\u0648 \\u0643\\u062A\\u064A\\u0631. \\u0646\\u064A\\u0627\\u0644\\u0646\\u0627."
t["Birds don't know the world ended. I envy them for that."] = "\\u0627\\u0644\\u0639\\u0635\\u0627\\u0641\\u064A\\u0631 \\u0645\\u0627 \\u0628\\u062A\\u0639\\u0631\\u0641 \\u0625\\u0646 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0644\\u0635\\u062A. \\u0628\\u062D\\u0633\\u062F\\u0647\\u0627."
t["Bite confirmed. Keeping the tension steady."] = "\\u0641\\u064A \\u0639\\u0636\\u0629 \\u0623\\u0643\\u064A\\u062F\\u0629. \\u0639\\u0645 \\u0636\\u0644 \\u0634\\u0627\\u062F\\u0629 \\u0627\\u0644\\u062E\\u064A\\u0637 \\u0628\\u0647\\u062F\\u0648\\u0621."
t["Blast it, a pair of them."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627, \\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0646."
t["Blast it, don't let both reach me!"] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627, \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u064A\\u0648\\u0635\\u0644\\u0648\\u0627 \\u0644\\u0639\\u0646\\u062F\\u064A!"
t["Blast it, one of them is here!"] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627, \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0646 \\u0647\\u0648\\u0646!"
t["Blast it. Dead at last."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627. \\u0645\\u0627\\u062A \\u0623\\u062E\\u064A\\u0631\\u0627."
t["Blast it. I need a minute before I say something worse."] = "\\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631. \\u0628\\u062F\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0642\\u0648\\u0644 \\u0634\\u064A \\u0623\\u0633\\u0648\\u0623."
t["Blast it. We needed this crop."] = "\\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631. \\u0643\\u0646\\u0627 \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646 \\u0647\\u0627\\u0644\\u0632\\u0631\\u0639."
t["Blast, that stung. Watch your reach."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627\\u060C \\u0648\\u062C\\u0639\\u062A\\u0646\\u064A. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0648\\u064A\\u0646 \\u0628\\u062A\\u0648\\u0635\\u0644 \\u0625\\u064A\\u062F\\u0643."
t["Blast, that's a whole group."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627, \\u0647\\u064A \\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629."
t["Blast. It took the bait and left me a story."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627. \\u0623\\u0643\\u0644\\u062A \\u0627\\u0644\\u0637\\u0639\\u0645 \\u0648\\u062A\\u0631\\u0643\\u062A\\u0644\\u064A \\u0642\\u0635\\u0629."
t["Bless your heart. Hold still!"] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u0639\\u064A\\u0646\\u0643. \\u0627\\u062B\\u0628\\u062A!"
t["Blood didn't do this. Staying did."] = "\\u0645\\u0648 \\u0627\\u0644\\u062F\\u0645 \\u0627\\u0644\\u0644\\u064A \\u062C\\u0645\\u0639\\u0646\\u0627. \\u0627\\u0644\\u0644\\u064A \\u062C\\u0645\\u0639\\u0646\\u0627 \\u0625\\u0646\\u0643 \\u0628\\u0642\\u064A\\u062A."
t["Blood first, fear later. Hold on."] = "\\u0627\\u0644\\u062F\\u0645 \\u0623\\u0648\\u0644\\u060C \\u0648\\u0627\\u0644\\u062E\\u0648\\u0641 \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0627\\u0635\\u0645\\u062F."
t["Blue moon over a broken water tower..."] = "\\u0642\\u0645\\u0631 \\u0623\\u0632\\u0631\\u0642 \\u0641\\u0648\\u0642 \\u062E\\u0632\\u0627\\u0646 \\u0645\\u064A \\u0645\\u0643\\u0633\\u0648\\u0631..."
t["Bluegrass section. Somebody grab a banjo. Or don't."] = "\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0628\\u0644\\u0648\\u063A\\u0631\\u0627\\u0633. \\u062D\\u062F\\u0627 \\u064A\\u0627\\u062E\\u062F \\u0628\\u0627\\u0646\\u062C\\u0648. \\u0623\\u0648 \\u0644\\u0623."
t["Book complete. I'll try the method before I recommend it."] = "\\u062E\\u0644\\u0635 \\u0627\\u0644\\u0643\\u062A\\u0627\\u0628. \\u0628\\u062C\\u0631\\u0628 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0623\\u0646\\u0635\\u062D \\u0641\\u064A\\u0647\\u0627."
t["Boots off soon. Stories later. Most of them true."] = "\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B \\u0645\\u0646\\u0634\\u0644\\u062D \\u0627\\u0644\\u0628\\u0648\\u0637. \\u0627\\u0644\\u0642\\u0635\\u0635 \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0623\\u063A\\u0644\\u0628\\u0647\\u0627 \\u0635\\u062D\\u064A\\u062D."
t["Boss. Just you and me. I got bit."] = "\\u0645\\u0639\\u0644\\u0645. \\u0628\\u0633 \\u0623\\u0646\\u0627 \\u0648\\u0625\\u0646\\u062A. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["Both of them are on us! Move!"] = "\\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u0639\\u0644\\u064A\\u0646\\u0627! \\u062A\\u062D\\u0631\\u0643!"
t["Both of you! Come on!"] = "\\u0625\\u0646\\u062A\\u0648 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646! \\u062A\\u0639\\u0627\\u0644\\u0648\\u0627!"
t["Bourbon ages better than people, it turns out."] = "\\u0627\\u0644\\u0628\\u0648\\u0631\\u0628\\u0648\\u0646 \\u0628\\u064A\\u0639\\u062A\\u0642 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0634\\u0631\\u060C \\u0637\\u0644\\u0639."
t["Bourbon ages better than people. Hell, bourbon ages better than anything."] = "\\u0627\\u0644\\u0628\\u0648\\u0631\\u0628\\u0648\\u0646 \\u0628\\u064A\\u0639\\u062A\\u0642 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0634\\u0631. \\u064A\\u0644\\u0639\\u0646\\u060C \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0623\\u064A \\u0634\\u064A."
t["Bourbon will outlive everybody. Kentucky planned ahead."] = "\\u0627\\u0644\\u0628\\u0648\\u0631\\u0628\\u0648\\u0646 \\u0631\\u062D \\u064A\\u0639\\u064A\\u0634 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0643\\u0644. \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A \\u062D\\u0627\\u0633\\u0628\\u0629 \\u062D\\u0633\\u0627\\u0628\\u0647\\u0627."
t["Brain just said what if. I told it not now."] = "\\u0639\\u0642\\u0644\\u064A \\u0642\\u0627\\u0644 \\u0634\\u0648 \\u0644\\u0648. \\u0642\\u0644\\u062A\\u0644\\u0647 \\u0645\\u0648 \\u0647\\u0644\\u0623."
t["Brain keeps asking what I'd look like as one of them. Taller, probably."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0636\\u0644 \\u064A\\u0633\\u0623\\u0644 \\u0643\\u064A\\u0641 \\u0628\\u0637\\u0644\\u0639 \\u0625\\u0630\\u0627 \\u0635\\u0631\\u062A \\u0645\\u0646\\u0647\\u0645. \\u0623\\u0637\\u0648\\u0644\\u060C \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627."
t["Brain says honk the horn of the next car we pass. Brain is fired."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0632\\u0645\\u0651\\u0631 \\u0644\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0628\\u0646\\u0645\\u0631\\u0642 \\u062C\\u0646\\u0628\\u0647\\u0627. \\u0639\\u0642\\u0644\\u064A \\u0645\\u0637\\u0631\\u0648\\u062F."
t["Brain says honk the horn of the next car. Brain is fired. Dumbass brain."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0632\\u0645\\u0651\\u0631 \\u0644\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629. \\u0639\\u0642\\u0644\\u064A \\u0645\\u0637\\u0631\\u0648\\u062F. \\u0639\\u0642\\u0644 \\u062D\\u0645\\u0627\\u0631."
t["Brain says savour it. Brain also says it might be the last."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0633\\u062A\\u0645\\u062A\\u0639\\u064A. \\u0648\\u0639\\u0642\\u0644\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u064A\\u0645\\u0643\\u0646 \\u0622\\u062E\\u0631 \\u0645\\u0631\\u0629."
t["Brain suggests a war cry. Brain has never considered consequences."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u062A\\u0631\\u062D \\u0635\\u0631\\u062E\\u0629 \\u062D\\u0631\\u0628. \\u0639\\u0642\\u0644\\u064A \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0641\\u0643\\u0631 \\u0628\\u0627\\u0644\\u0639\\u0648\\u0627\\u0642\\u0628."
t["Brain suggests a war cry. Brain has never given a damn about consequences."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u062A\\u0631\\u062D \\u0635\\u0631\\u062E\\u0629 \\u062D\\u0631\\u0628. \\u0639\\u0642\\u0644\\u064A \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0647\\u0645\\u0651\\u0647 \\u0627\\u0644\\u0639\\u0648\\u0627\\u0642\\u0628 \\u064A\\u0644\\u0639\\u0646\\u0647."
t["Brain suggests you might be the dangerous one. Brain is outvoted."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0642\\u062A\\u0631\\u062D \\u0625\\u0646\\u0643 \\u0625\\u0646\\u062A \\u0627\\u0644\\u062E\\u0637\\u064A\\u0631. \\u0639\\u0642\\u0644\\u064A \\u062E\\u0633\\u0631 \\u0627\\u0644\\u062A\\u0635\\u0648\\u064A\\u062A."
t["Brandenburg roads could lead you to a church or a liquor store."] = "\\u0637\\u0631\\u0642\\u0627\\u062A \\u0628\\u0631\\u0627\\u0646\\u062F\\u0646\\u0628\\u0631\\u063A \\u064A\\u0627 \\u0628\\u062A\\u0648\\u062F\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0643\\u0646\\u064A\\u0633\\u0629 \\u064A\\u0627 \\u0639\\u0627\\u0644\\u062E\\u0645\\u0627\\u0631\\u0629."
t["Bread, if we ever get the flour. I'd even wash the dishes."] = "\\u062E\\u0628\\u0632\\u060C \\u0625\\u0630\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 \\u0637\\u062D\\u064A\\u0646. \\u062D\\u062A\\u0649 \\u0628\\u062C\\u0644\\u064A \\u0627\\u0644\\u0635\\u062D\\u0648\\u0646."
t["Break away before they flank us!"] = "\\u0627\\u0628\\u0639\\u062F \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0644\\u062A\\u0641\\u0648\\u0627 \\u0639\\u0644\\u064A\\u0646\\u0627!"
t["Break contact with the lone walker!"] = "\\u0627\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0648\\u0627\\u062D\\u062F \\u0647\\u0627\\u062F!"
t["Break contact!"] = "\\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u0646!"
t["Break contact! The whole horde is coming!"] = "\\u0627\\u0628\\u0639\\u062F! \\u0627\\u0644\\u0645\\u0648\\u062C\\u0629 \\u0643\\u0644\\u0647\\u0627 \\u062C\\u0627\\u064A\\u0629!"
t["Break sight as soon as the path opens!"] = "\\u063A\\u064A\\u0628 \\u0639\\u0646 \\u0639\\u064A\\u0646\\u0646 \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u064A\\u0646\\u0641\\u062A\\u062D \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642!"
t["Break sight, cross the fence, don't look back."] = "\\u063A\\u064A\\u0628 \\u0639\\u0646 \\u0639\\u064A\\u0646\\u0646, \\u0627\\u0642\\u0637\\u0639 \\u0627\\u0644\\u0633\\u0648\\u0631, \\u0648\\u0644\\u0627 \\u062A\\u062A\\u0637\\u0644\\u0639 \\u0648\\u0631\\u0627\\u0643."
t["Break their grip, then pull me up!"] = "\\u0641\\u0643 \\u0645\\u0633\\u0643\\u062A\\u0646, \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0642\\u0648\\u0645\\u0646\\u064A!"
t["Breaking glass. Either somebody's desperate or something's hungry."] = "\\u0642\\u0632\\u0627\\u0632 \\u0639\\u0645 \\u064A\\u062A\\u0643\\u0633\\u0631. \\u064A\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0627\\u0626\\u0633\\u060C \\u064A\\u0627 \\u0634\\u064A \\u062C\\u0648\\u0639\\u0627\\u0646."
t["Bring a fueled blowtorch. Heat is part of the instructions."] = "\\u062C\\u064A\\u0628 \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649. \\u0627\\u0644\\u0646\\u0627\\u0631 \\u062C\\u0632\\u0621 \\u0645\\u0646 \\u0627\\u0644\\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A."
t["Bring a usable prying tool. That board is staying put."] = "\\u062C\\u064A\\u0628 \\u0639\\u062F\\u0629 \\u062E\\u0644\\u0639 \\u062A\\u0646\\u0641\\u0639. \\u0647\\u0627\\u0644\\u0644\\u0648\\u062D \\u0645\\u0648 \\u0646\\u0627\\u0648\\u064A \\u064A\\u062A\\u062D\\u0631\\u0643."
t["Bring a working saw before I start bargaining with the log."] = "\\u062C\\u064A\\u0628 \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0634\\u063A\\u0651\\u0627\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0635\\u064A\\u0631 \\u0641\\u0627\\u0648\\u0636 \\u062C\\u0630\\u0639 \\u0627\\u0644\\u0634\\u062C\\u0631\\u0629."
t["Bring me a lure and I'll try that water again."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0637\\u0639\\u0645 \\u0648\\u0628\\u062C\\u0631\\u0651\\u0628 \\u0647\\u0627\\u0644\\u0645\\u064A \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Bring me a pan and I'll get this started."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0648\\u0628\\u0628\\u0644\\u0651\\u0634."
t["Bring me a plank and I can continue."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0644\\u0648\\u062D \\u062E\\u0634\\u0628 \\u0648\\u0628\\u0643\\u0641\\u0651\\u064A."
t["Bring me a pot and I'll make something of this."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629 \\u0648\\u0628\\u0637\\u0644\\u0651\\u0639 \\u0634\\u064A \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0627\\u062A."
t["Bring me a saw and I'll get the planks done."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0648\\u0628\\u062E\\u0644\\u0651\\u0635\\u0644\\u0643 \\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u062D."
t["Bring me a torch with fuel and I'll handle it."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0641\\u064A \\u0648\\u0642\\u0648\\u062F \\u0648\\u0623\\u0646\\u0627 \\u0628\\u062A\\u0635\\u0631\\u0641."
t["Bring one plank. Air has terrible structural strength."] = "\\u062C\\u064A\\u0628\\u0644\\u064A \\u0644\\u0648\\u062D. \\u0627\\u0644\\u0647\\u0648\\u0627 \\u0645\\u0627 \\u0628\\u064A\\u062D\\u0645\\u0644 \\u0633\\u0642\\u0641."
t["Bring two nails. Good intentions don't hold a board."] = "\\u062C\\u064A\\u0628 \\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646. \\u0627\\u0644\\u0646\\u064A\\u0629 \\u0627\\u0644\\u0637\\u064A\\u0628\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0645\\u0633\\u0643 \\u062E\\u0634\\u0628\\u0629."
t["Bring water and a blanket. They're scared too."] = "\\u062C\\u064A\\u0628\\u0648\\u0627 \\u0645\\u064A \\u0648\\u062D\\u0631\\u0627\\u0645. \\u0647\\u0646\\u0646 \\u0643\\u0645\\u0627\\u0646 \\u062E\\u0627\\u064A\\u0641\\u064A\\u0646."
t["Bringing the water over now."] = "\\u062C\\u0627\\u064A\\u0628\\u0629 \\u0627\\u0644\\u0645\\u064A \\u0647\\u0644\\u0623."
t["Broke free!"] = "\\u0641\\u0644\\u062A!"
t["Bucket's empty. Story of '93."] = "\\u0627\\u0644\\u0633\\u0637\\u0644 \\u0641\\u0627\\u0636\\u064A. \\u0642\\u0635\\u0629 \\u0627\\u0644\\u064093."
t["Burn what needs burning. Keep the room safe."] = "\\u0627\\u062D\\u0631\\u0642 \\u0627\\u0644\\u0644\\u064A \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0646\\u062D\\u0631\\u0642. \\u062E\\u0644\\u064A \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0623\\u0645\\u0627\\u0646."
t["Bury what's left of me somewhere with a view. If you can."] = "\\u0627\\u062F\\u0641\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0636\\u0644 \\u0645\\u0646\\u064A \\u0628\\u0645\\u0637\\u0631\\u062D \\u0625\\u0644\\u0647 \\u0645\\u0646\\u0638\\u0631. \\u0625\\u0630\\u0627 \\u0641\\u064A\\u0643."
t["Busy hands, full shelves. That's the whole plan."] = "\\u0625\\u064A\\u062F\\u064A\\u0646 \\u0634\\u063A\\u0627\\u0644\\u0629 \\u0648\\u0631\\u0641\\u0648\\u0641 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629. \\u0647\\u064A \\u0643\\u0644 \\u0627\\u0644\\u062E\\u0637\\u0629."
t["Buy one, get one! I'm on it!"] = "\\u0627\\u0634\\u062A\\u0631\\u064A \\u0648\\u0627\\u062D\\u062F \\u0648\\u062E\\u062F \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A \\u0628\\u0628\\u0644\\u0627\\u0634! \\u0647\\u0627\\u062F \\u0639\\u0646\\u062F\\u064A!"
t["C'mere, you sorry thing!"] = "\\u062A\\u0639\\u0627\\u0644 \\u0644\\u0647\\u0648\\u0646 \\u064A\\u0627 \\u0645\\u0633\\u0643\\u064A\\u0646!"
t["Cafeteria trays. Lunch survived mostly unchanged, I expect."] = "\\u0635\\u0648\\u0627\\u0646\\u064A \\u0627\\u0644\\u0643\\u0627\\u0641\\u064A\\u062A\\u0631\\u064A\\u0627. \\u0627\\u0644\\u063A\\u062F\\u0627 \\u0628\\u0642\\u064A \\u0639\\u0644\\u0649 \\u062D\\u0627\\u0644\\u0647 \\u062A\\u0642\\u0631\\u064A\\u0628\\u064B\\u0627\\u060C \\u0628\\u062A\\u0648\\u0642\\u0639."
t["Call me %2 again and see what happens."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %2 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629 \\u0648\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0628\\u064A\\u0635\\u064A\\u0631."
t["Call me %2 one more time, you son of a bitch."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %2 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629\\u060C \\u064A\\u0627 \\u0627\\u0628\\u0646 \\u0627\\u0644\\u0643\\u0644\\u0628."
t["Call me %2 one more time, you son of a gun."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %2 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629\\u060C \\u064A\\u0627 \\u0645\\u0644\\u0639\\u0648\\u0646."
t["Call me %2. Only my mother called me %1."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %2. \\u0628\\u0633 \\u0625\\u0645\\u064A \\u0643\\u0627\\u0646\\u062A \\u062A\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %1."
t["Call me that if you must. I won't like it."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A \\u0647\\u064A\\u0643 \\u0625\\u0630\\u0627 \\u0645\\u0635\\u0631. \\u0645\\u0648 \\u0631\\u062D \\u064A\\u0639\\u062C\\u0628\\u0646\\u064A."
t["Can we find a digging tool? I've got work waiting outside."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u0644\\u0644\\u062D\\u0641\\u0631\\u061F \\u0641\\u064A \\u0634\\u063A\\u0644 \\u0646\\u0627\\u0637\\u0631\\u0646\\u064A \\u0628\\u0631\\u0651\\u0627."
t["Can we find enough water without leaving anyone short?"] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0645\\u064A \\u0628\\u062A\\u0643\\u0641\\u064A \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0646\\u062D\\u0631\\u0645\\u061F"
t["Can we get the stove working before I start dinner?"] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0634\\u063A\\u0651\\u0644 \\u0627\\u0644\\u063A\\u0627\\u0632 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0628\\u0644\\u0651\\u0634 \\u0628\\u0627\\u0644\\u0639\\u0634\\u0627\\u061F"
t["Can we look for a working saw? The lumber is waiting."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0634\\u063A\\u0651\\u0627\\u0644\\u061F \\u0627\\u0644\\u062E\\u0634\\u0628 \\u0646\\u0627\\u0637\\u0631."
t["Can we plan a supply run before anyone goes without?"] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0631\\u062A\\u0628 \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0645\\u0648\\u0646\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0636\\u0644 \\u0628\\u0644\\u0627\\u061F"
t["Can we search for worms or a usable lure?"] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u062F\\u0648\\u062F \\u0623\\u0648 \\u0637\\u0639\\u0645 \\u064A\\u0646\\u0641\\u0639\\u061F"
t["Can we talk? Just us. It's bad."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A\\u061F \\u0628\\u0633 \\u0646\\u062D\\u0646\\u0627. \\u0627\\u0644\\u0642\\u0635\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629."
t["Can you find a pan in one of those kitchens?"] = "\\u0641\\u064A\\u0643 \\u062A\\u0644\\u0627\\u0642\\u064A \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0628\\u0634\\u064A \\u0645\\u0637\\u0628\\u062E \\u0645\\u0646 \\u0647\\u062F\\u0648\\u0644\\u061F"
t["Can you hear me over the weather?"] = "\\u0633\\u0627\\u0645\\u0639\\u0646\\u064A \\u0641\\u0648\\u0642 \\u0635\\u0648\\u062A \\u0627\\u0644\\u0637\\u0642\\u0633\\u061F"
t["Can you look for a couple of clean bowls?"] = "\\u0641\\u064A\\u0643 \\u062A\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0643\\u0645 \\u0632\\u0628\\u062F\\u064A\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629\\u061F"
t["Can you spare a hammer? This job's stopped without it."] = "\\u0645\\u0639\\u0643 \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0632\\u064A\\u0627\\u062F\\u0629\\u061F \\u0627\\u0644\\u0634\\u063A\\u0644 \\u0648\\u0627\\u0642\\u0641 \\u0628\\u0644\\u0627\\u0647."
t["Can you spare a rod for the fishing?"] = "\\u0645\\u0639\\u0643 \\u0635\\u0646\\u0627\\u0631\\u0629 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0644\\u0644\\u0635\\u064A\\u062F\\u061F"
t["Can you spare a sharp knife for the cooking?"] = "\\u0645\\u0639\\u0643 \\u0633\\u0643\\u064A\\u0646\\u0629 \\u062D\\u0627\\u062F\\u0629 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0644\\u0644\\u0637\\u0628\\u062E\\u061F"
t["Can't beat them from here. I'm lining up another shot."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0639\\u0644\\u064A\\u0647\\u0645 \\u0645\\u0646 \\u0647\\u0648\\u0646. \\u0639\\u0645 \\u062F\\u0648\\u0651\\u0631 \\u0639\\u0644\\u0649 \\u0637\\u0644\\u0642\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Can't cover three approaches. I'm withdrawing to one."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u063A\\u0637\\u064A \\u062A\\u0644\\u0627\\u062A \\u0637\\u0631\\u0642. \\u0639\\u0645 \\u0627\\u0646\\u0633\\u062D\\u0628 \\u0644\\u0637\\u0631\\u064A\\u0642 \\u0648\\u0627\\u062D\\u062F."
t["Can't fight a whole compass. I'm heading for that opening."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0642\\u0627\\u062A\\u0644 \\u0627\\u0644\\u0628\\u0648\\u0635\\u0644\\u0629 \\u0643\\u0644\\u0647\\u0627. \\u0631\\u0627\\u064A\\u062D\\u0629 \\u0639\\u0647\\u062F\\u064A\\u0643 \\u0627\\u0644\\u0641\\u062A\\u062D\\u0629."
t["Can't fight on fumes. I'm holding back till I recover."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0642\\u0627\\u062A\\u0644 \\u0639\\u0627\\u0644\\u0631\\u064A\\u062D\\u0629. \\u0631\\u062D \\u0636\\u0644 \\u0648\\u0631\\u0627 \\u0644\\u0627\\u0631\\u062A\\u0627\\u062D."
t["Can't fight what we can't see. Stay close."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0642\\u0627\\u062A\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0627 \\u0645\\u0646\\u0634\\u0648\\u0641\\u0647. \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628."
t["Can't fight while stumbling. I'm getting clear of this mess."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0642\\u0627\\u062A\\u0644 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0639\\u062A\\u0631. \\u0639\\u0645 \\u0637\\u0644\\u0639 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u062E\\u0628\\u0635\\u0629."
t["Can't fight with a blocked retreat. I'm finding another route."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0642\\u0627\\u062A\\u0644 \\u0648\\u0637\\u0631\\u064A\\u0642 \\u0631\\u062C\\u0639\\u062A\\u064A \\u0645\\u0633\\u0643\\u0631\\u0629. \\u0639\\u0645 \\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u063A\\u064A\\u0631\\u0647\\u0627."
t["Can't flatten them wheezing. I'm catching air, then coming back."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u062F\\u0639\\u0633\\u0647\\u0645 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0634\\u0647\\u0651\\u0642. \\u0628\\u0627\\u062E\\u062F \\u0646\\u0641\\u0633 \\u0648\\u0631\\u0627\\u062C\\u0639\\u0629."
t["Can't hit them with optimism. I'm coming back for equipment."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0636\\u0631\\u0628\\u0647\\u0646 \\u0628\\u0627\\u0644\\u062A\\u0641\\u0627\\u0624\\u0644. \\u0631\\u0627\\u062C\\u0639\\u0629 \\u062C\\u064A\\u0628 \\u0639\\u062F\\u0629."
t["Can't retreat from a dead end. I'm finding another entrance."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0646\\u0633\\u062D\\u0628 \\u0645\\u0646 \\u0637\\u0631\\u064A\\u0642 \\u0645\\u0633\\u0643\\u0631\\u0629. \\u0639\\u0645 \\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0645\\u062F\\u062E\\u0644 \\u062A\\u0627\\u0646\\u064A."
t["Can't salvage this properly without a screwdriver."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0651\\u0647 \\u0645\\u0646\\u064A\\u062D \\u0628\\u0644\\u0627 \\u0645\\u0641\\u0643."
t["Can't shoot a promise. I'm pulling back to reload."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0642\\u0648\\u0651\\u0633 \\u0648\\u0639\\u0648\\u062F. \\u0631\\u0627\\u062C\\u0639\\u0629 \\u0639\\u0628\\u064A."
t["Can't swing and breathe together. I'm taking a breather."] = "\\u064A\\u0627 \\u0628\\u0636\\u0631\\u0628 \\u064A\\u0627 \\u0628\\u062A\\u0646\\u0641\\u0633\\u060C \\u0627\\u0644\\u0627\\u062A\\u0646\\u064A\\u0646 \\u0633\\u0648\\u0627 \\u0644\\u0623. \\u0628\\u062F\\u064A \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629."
t["Can't swing through walls. I'm taking this outside."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0631\\u0628 \\u0645\\u0646 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646. \\u0631\\u062D \\u0637\\u0644\\u0639\\u0647\\u0627 \\u0628\\u0631\\u0627."
t["Can't swing without catching somebody. I'm moving to open ground."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0631\\u0628 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0635\\u064A\\u0628 \\u062D\\u062F\\u0627. \\u0639\\u0645 \\u0631\\u0648\\u062D \\u0639\\u0645\\u0637\\u0631\\u062D \\u0645\\u0641\\u062A\\u0648\\u062D."
t["Can't trade blows on credit. I'm stopping to patch up."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0627\\u0631\\u0628 \\u0628\\u0627\\u0644\\u062F\\u064A\\u0646. \\u0639\\u0645 \\u0648\\u0642\\u0641 \\u0636\\u0645\\u062F \\u062D\\u0627\\u0644\\u064A."
t["Can't trust it for another swing. I'm backing off."] = "\\u0645\\u0627 \\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0647 \\u0644\\u0636\\u0631\\u0628\\u0629 \\u0643\\u0645\\u0627\\u0646. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["Can't win that wager. I'm keeping my stake and retreating."] = "\\u0631\\u0647\\u0627\\u0646 \\u062E\\u0633\\u0631\\u0627\\u0646. \\u0628\\u0634\\u064A\\u0644 \\u0645\\u0635\\u0631\\u064A\\u0627\\u062A\\u064A \\u0648\\u0628\\u0646\\u0633\\u062D\\u0628."
t["Car rides used to mean somewhere fun. Now they mean somewhere less bad."] = "\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u0643\\u0627\\u0646 \\u064A\\u0639\\u0646\\u064A \\u0645\\u062D\\u0644 \\u062D\\u0644\\u0648. \\u0647\\u0644\\u0623 \\u064A\\u0639\\u0646\\u064A \\u0645\\u062D\\u0644 \\u0623\\u0642\\u0644 \\u0633\\u0648\\u0621."
t["Careful answer:"] = "\\u062C\\u0648\\u0627\\u0628 \\u0645\\u062D\\u0633\\u0648\\u0628:"
t["Careful picking. We need seed as much as food."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627 \\u0628\\u0627\\u0644\\u0642\\u0637\\u0641. \\u0628\\u062F\\u0646\\u0627 \\u0628\\u0632\\u0627\\u0631 \\u0642\\u062F \\u0645\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0623\\u0643\\u0644."
t["Careful with the seed. Every one matters."] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0628\\u0632\\u0627\\u0631. \\u0643\\u0644 \\u0648\\u062D\\u062F\\u0629 \\u0628\\u062A\\u0641\\u0631\\u0642."
t["Careful, that's my shoulder."] = "\\u0627\\u0646\\u062A\\u0628\\u0647\\u060C \\u0647\\u0627\\u062F \\u0643\\u062A\\u0641\\u064A."
t["Careful. I do not know what is on that."] = "\\u0627\\u0646\\u062A\\u0628\\u0647. \\u0645\\u0627 \\u0628\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u0639\\u0644\\u064A\\u0647."
t["Careful. That was me you hit."] = "\\u0627\\u0646\\u062A\\u0628\\u0647. \\u0623\\u0646\\u0627 \\u0627\\u0644\\u0644\\u064A \\u0636\\u0631\\u0628\\u062A\\u0646\\u064A."
t["Cash still in the tip jar. Nobody's that desperate. Yet."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A \\u0645\\u0635\\u0627\\u0631\\u064A \\u0628\\u0639\\u0644\\u0628\\u0629 \\u0627\\u0644\\u0628\\u0642\\u0634\\u064A\\u0634. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0627\\u0626\\u0633 \\u0644\\u0647\\u0627\\u0644\\u062F\\u0631\\u062C\\u0629. \\u0644\\u0633\\u0627."
t["Cast is out. Now we wait."] = "\\u0631\\u0645\\u064A\\u062A \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629. \\u0647\\u0644\\u0623 \\u0645\\u0646\\u0633\\u062A\\u0646\\u0649."
t["Casting again. Dinner hasn't agreed to the terms."] = "\\u0639\\u0645 \\u0627\\u0631\\u0645\\u064A \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0627\\u0644\\u0639\\u0634\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0648\\u0627\\u0641\\u0642 \\u0639\\u0627\\u0644\\u0634\\u0631\\u0648\\u0637."
t["Caught it early. I can still help it."] = "\\u0644\\u062D\\u0642\\u062A\\u0647\\u0627 \\u0628\\u0643\\u064A\\u0631. \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0633\\u0627\\u0639\\u062F\\u0647\\u0627."
t["Caught it. Something alive made the trip home worthwhile."] = "\\u0635\\u062F\\u062A\\u0647\\u0627. \\u0634\\u064A \\u0639\\u0627\\u064A\\u0634 \\u062E\\u0644\\u0651\\u0649 \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u0631\\u062C\\u0639\\u0629 \\u064A\\u0633\\u062A\\u0627\\u0647\\u0644."
t["Cells kept people in. Right now I'd settle for keeping things out."] = "\\u0627\\u0644\\u0632\\u0646\\u0627\\u0632\\u064A\\u0646 \\u0643\\u0627\\u0646\\u062A \\u062A\\u062D\\u0628\\u0633 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u062C\\u0648\\u0627. \\u0647\\u0644\\u0623 \\u0628\\u0631\\u0636\\u0649 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0627\\u062A \\u0628\\u0631\\u0627."
t["Certainty has killed more people than doubt ever did."] = "\\u0627\\u0644\\u064A\\u0642\\u064A\\u0646 \\u0642\\u062A\\u0644 \\u0646\\u0627\\u0633 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0643 \\u0628\\u0643\\u062A\\u064A\\u0631."
t["Chalkboard says 'Test on Monday'. Test's cancelled, kids."] = "\\u0639\\u0627\\u0644\\u0644\\u0648\\u062D \\u0645\\u0643\\u062A\\u0648\\u0628: \\u0627\\u0645\\u062A\\u062D\\u0627\\u0646 \\u064A\\u0648\\u0645 \\u0627\\u0644\\u0627\\u062A\\u0646\\u064A\\u0646. \\u0627\\u0646\\u0644\\u063A\\u0649 \\u064A\\u0627 \\u0648\\u0644\\u0627\\u062F."
t["Channel's clear on my end. You copy?"] = "\\u0627\\u0644\\u0642\\u0646\\u0627\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0645\\u0646 \\u0639\\u0646\\u062F\\u064A. \\u0648\\u0627\\u0635\\u0644\\u0643\\u061F"
t["Cheap sheets make good bandages. Just saying."] = "\\u0627\\u0644\\u0634\\u0631\\u0627\\u0634\\u0641 \\u0627\\u0644\\u0631\\u062E\\u064A\\u0635\\u0629 \\u0628\\u062A\\u0639\\u0645\\u0644 \\u0636\\u0645\\u0627\\u062F\\u0627\\u062A \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0628\\u0642\\u0648\\u0644 \\u0628\\u0633."
t["Check every bag. We are short on supplies."] = "\\u0641\\u062A\\u0634 \\u0643\\u0644 \\u0634\\u0646\\u0637\\u0629. \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0639\\u0646\\u0627 \\u0646\\u0627\\u0642\\u0635\\u0629."
t["Check the cupboards for a usable cooking pot."] = "\\u0634\\u0648\\u0641 \\u0628\\u0627\\u0644\\u062E\\u0632\\u0627\\u064A\\u0646 \\u0625\\u0630\\u0627 \\u0641\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629 \\u062A\\u0646\\u0641\\u0639."
t["Check the door. Check it again. I don't trust me anymore."] = "\\u0634\\u064A\\u0651\\u0643 \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0648\\u0634\\u064A\\u0643\\u0647 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0648\\u0627\\u062B\\u0642\\u0629 \\u0628\\u062D\\u0627\\u0644\\u064A."
t["Check the doors after. Grief makes people careless."] = "\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628 \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0627\\u0644\\u062D\\u0632\\u0646 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0646\\u0627\\u0633 \\u062A\\u063A\\u0644\\u0637."
t["Check the expiry dates. Then ignore them if you have to."] = "\\u0634\\u0648\\u0641 \\u062A\\u0627\\u0631\\u064A\\u062E \\u0627\\u0644\\u0627\\u0646\\u062A\\u0647\\u0627\\u0621. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0637\\u0646\\u0651\\u0634 \\u0625\\u0630\\u0627 \\u0627\\u0636\\u0637\\u0631\\u064A\\u062A."
t["Check the garages for a usable blowtorch."] = "\\u0634\\u0648\\u0641 \\u0628\\u0627\\u0644\\u0643\\u0631\\u0627\\u062C\\u0627\\u062A \\u0625\\u0630\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u064A\\u0646\\u0641\\u0639."
t["Check the racks. Somebody else may have had the same idea first."] = "\\u0641\\u062A\\u0634 \\u0627\\u0644\\u0631\\u0641\\u0648\\u0641. \\u064A\\u0645\\u0643\\u0646 \\u062D\\u062F\\u0627 \\u0633\\u0628\\u0642\\u0646\\u0627 \\u0639\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0641\\u0643\\u0631\\u0629."
t["Check the rooms. Keep an ear on the door."] = "\\u0634\\u064A\\u0643\\u0648\\u0627 \\u0627\\u0644\\u063A\\u0631\\u0641. \\u0648\\u0623\\u062F\\u0646 \\u0639\\u0627\\u0644\\u0628\\u0627\\u0628."
t["Check the wound every hour. Write it down."] = "\\u0634\\u064A\\u0651\\u0643\\u0648\\u0627 \\u0627\\u0644\\u062C\\u0631\\u062D \\u0643\\u0644 \\u0633\\u0627\\u0639\\u0629. \\u0648\\u0627\\u0643\\u062A\\u0628\\u0648\\u0647\\u0627."
t["Check your straps. I won't stop twice for loose gear."] = "\\u0634\\u064A\\u0643\\u0648\\u0627 \\u0623\\u062D\\u0632\\u0645\\u062A\\u0643\\u0645. \\u0645\\u0627 \\u0628\\u0648\\u0642\\u0641 \\u0645\\u0631\\u062A\\u064A\\u0646 \\u0645\\u0634\\u0627\\u0646 \\u0639\\u062F\\u0629 \\u0645\\u0631\\u062E\\u064A\\u0629."
t["Checking in before the batteries surprise us."] = "\\u0639\\u0645 \\u0634\\u064A\\u0643 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0631\\u064A\\u0627\\u062A \\u062A\\u0641\\u0627\\u062C\\u0626\\u0646\\u0627."
t["Checking range and signal. Who's still with us?"] = "\\u0639\\u0645 \\u0634\\u064A\\u0643 \\u0627\\u0644\\u0645\\u062F\\u0649 \\u0648\\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629. \\u0645\\u064A\\u0646 \\u0644\\u0633\\u0627 \\u0645\\u0639\\u0646\\u0627\\u061F"
t["Checking the channel. Give me a word if you're listening."] = "\\u0639\\u0645 \\u0634\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0642\\u0646\\u0627\\u0629. \\u0642\\u0648\\u0644 \\u0643\\u0644\\u0645\\u0629 \\u0625\\u0630\\u0627 \\u0633\\u0627\\u0645\\u0639."
t["Checking the team's frequency. Come back if you hear me."] = "\\u0639\\u0645 \\u0634\\u064A\\u0643 \\u0645\\u0648\\u062C\\u0629 \\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629. \\u0631\\u062F \\u0625\\u0630\\u0627 \\u0633\\u0627\\u0645\\u0639\\u0646\\u064A."
t["Checkout at eleven. Looks like everybody missed it."] = "\\u0627\\u0644\\u0645\\u063A\\u0627\\u062F\\u0631\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u062D\\u062F\\u0639\\u0634. \\u0634\\u0643\\u0644\\u0647 \\u0627\\u0644\\u0643\\u0644 \\u0641\\u0648\\u0651\\u062A\\u0647\\u0627."
t["Checkout lanes are clear. First time in county history."] = "\\u0645\\u0633\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u062F\\u0641\\u0639 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0644\\u0623\\u0648\\u0644 \\u0645\\u0631\\u0629 \\u0628\\u062A\\u0627\\u0631\\u064A\\u062E \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629."
t["Childproof caps. Civilization's last line of defense."] = "\\u0623\\u063A\\u0637\\u064A\\u0629 \\u0636\\u062F \\u0627\\u0644\\u0648\\u0644\\u0627\\u062F. \\u0622\\u062E\\u0631 \\u062E\\u0637 \\u062F\\u0641\\u0627\\u0639 \\u0644\\u0644\\u062D\\u0636\\u0627\\u0631\\u0629."
t["Christ almighty. Where do you even get these?"] = "\\u064A\\u0627 \\u0631\\u0628 \\u0627\\u0644\\u0633\\u0645\\u0627. \\u0645\\u0646 \\u0648\\u064A\\u0646 \\u0628\\u062A\\u062C\\u064A\\u0628 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A\\u061F"
t["Civil Defense assembly point. Form one orderly line, children."] = "\\u0646\\u0642\\u0637\\u0629 \\u062A\\u062C\\u0645\\u0639 \\u0627\\u0644\\u062F\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0645\\u062F\\u0646\\u064A. \\u0635\\u0641 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0631\\u062A\\u0628 \\u064A\\u0627 \\u0648\\u0644\\u0627\\u062F."
t["Civil Defense fitness standard: remain mobile. We are exceeding expectations."] = "\\u0645\\u0639\\u064A\\u0627\\u0631 \\u0644\\u064A\\u0627\\u0642\\u0629 \\u0627\\u0644\\u062F\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0645\\u062F\\u0646\\u064A: \\u0636\\u0644 \\u0645\\u062A\\u062D\\u0631\\u0643. \\u0639\\u0645 \\u0646\\u062A\\u062C\\u0627\\u0648\\u0632 \\u0627\\u0644\\u062A\\u0648\\u0642\\u0639\\u0627\\u062A."
t["Civil Defense information film at seven. Feature presentation postponed."] = "\\u0641\\u064A\\u0644\\u0645 \\u0627\\u0644\\u062F\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0645\\u062F\\u0646\\u064A \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u0633\\u0628\\u0639\\u0629. \\u0627\\u0644\\u0639\\u0631\\u0636 \\u0627\\u0644\\u0631\\u0626\\u064A\\u0633\\u064A \\u062A\\u0623\\u062C\\u0644."
t["Clean and quick. Moving in!"] = "\\u0646\\u0636\\u064A\\u0641 \\u0648\\u0633\\u0631\\u064A\\u0639. \\u0639\\u0645 \\u0642\\u0631\\u0628!"
t["Clean cloth, tight knot, then we move."] = "\\u0642\\u0645\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641\\u060C \\u0639\\u0642\\u062F\\u0629 \\u0642\\u0648\\u064A\\u0629\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0645\\u0634\\u064A."
t["Clean enough for supper, if anyone's asking."] = "\\u0646\\u0636\\u064A\\u0641 \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u0644\\u0639\\u0634\\u0627\\u060C \\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644."
t["Clean enough to know which stains are old."] = "\\u0646\\u0636\\u0641\\u062A \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0628\\u0639\\u0631\\u0641 \\u0623\\u064A \\u0628\\u0642\\u0639 \\u0642\\u062F\\u064A\\u0645\\u0629."
t["Clean water soon, before this becomes a problem."] = "\\u0645\\u064A \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B\\u060C \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0635\\u064A\\u0631 \\u0645\\u0634\\u0643\\u0644\\u0629."
t["Cleaner now. Smells like bleach, but cleaner."] = "\\u0623\\u0646\\u0636\\u0641 \\u0647\\u0644\\u0623. \\u0631\\u064A\\u062D\\u062A\\u0647 \\u0643\\u0644\\u0648\\u0631\\u060C \\u0628\\u0633 \\u0623\\u0646\\u0636\\u0641."
t["Clear head, steady hands. Let's use them."] = "\\u0631\\u0627\\u0633 \\u0635\\u0627\\u0641\\u064A \\u0648\\u0625\\u064A\\u062F\\u064A\\u0646 \\u062B\\u0627\\u0628\\u062A\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646\\u0647\\u0646."
t["Clear here. Check yourselves!"] = "\\u0646\\u0636\\u064A\\u0641 \\u0647\\u0648\\u0646. \\u0634\\u0648\\u0641\\u0648\\u0627 \\u062D\\u0627\\u0644\\u0643\\u0646!"
t["Clear it carefully. I don't want the next row catching this."] = "\\u0634\\u064A\\u0644\\u0647 \\u0639\\u0627\\u0644\\u0647\\u062F\\u0627. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0644\\u062E\\u0637 \\u0627\\u0644\\u062C\\u0627\\u064A \\u064A\\u0644\\u0642\\u0637 \\u0647\\u0627\\u062F."
t["Clear landing. Watch yours."] = "\\u0627\\u0644\\u0646\\u0632\\u0644\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0646\\u0632\\u0644\\u062A\\u0643."
t["Clear! It's down."] = "\\u0646\\u0636\\u064A\\u0641! \\u0648\\u0642\\u0639."
t["Click. That's the whole speech. I'm reloading."] = "\\u062A\\u0643. \\u0647\\u064A \\u0643\\u0644 \\u0627\\u0644\\u062E\\u0637\\u0628\\u0629. \\u0639\\u0645 \\u0639\\u0628\\u064A."
t["Clocking you out!"] = "\\u062E\\u0644\\u0635 \\u062F\\u0648\\u0627\\u0645\\u0643!"
t["Close in, but watch the exits!"] = "\\u0642\\u0631\\u0628\\u0648\\u0627\\u060C \\u0628\\u0633 \\u0639\\u064A\\u0646\\u0643\\u0645 \\u0639\\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C!"
t["Close. Let's not do that again."] = "\\u0643\\u0627\\u0646\\u062A \\u0642\\u0631\\u064A\\u0628\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u0639\\u064A\\u062F\\u0647\\u0627."
t["Closing in now!"] = "\\u0639\\u0645 \\u0642\\u0631\\u0628 \\u0647\\u0644\\u0623!"
t["Clothes back on. Let's see what needs doing."] = "\\u0644\\u0628\\u0633\\u062A \\u062A\\u064A\\u0627\\u0628\\u064A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0641\\u064A \\u0634\\u063A\\u0644."
t["Coffee or smoke, I'll take a warm room either way."] = "\\u0642\\u0647\\u0648\\u0629 \\u0623\\u0648 \\u062F\\u062E\\u0627\\u0646\\u060C \\u0628\\u0642\\u0628\\u0644 \\u0628\\u0623\\u0648\\u0636\\u0629 \\u062F\\u0627\\u0641\\u064A\\u0629 \\u0628\\u0643\\u0644 \\u0627\\u0644\\u0623\\u062D\\u0648\\u0627\\u0644."
t["Coin-op. I've got coins. Nothing to feed."] = "\\u0628\\u0627\\u0644\\u0641\\u0631\\u0627\\u0637\\u0629. \\u0645\\u0639\\u064A \\u0641\\u0631\\u0627\\u0637\\u0629. \\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0627\\u0637\\u0639\\u0645\\u064A\\u0647."
t["Cold air makes a simple job complicated."] = "\\u0627\\u0644\\u0628\\u0631\\u062F \\u0628\\u064A\\u0639\\u0642\\u062F \\u0634\\u063A\\u0644\\u0629 \\u0628\\u0633\\u064A\\u0637\\u0629."
t["Cold fingers, warm tubes. Let's see what survives."] = "\\u0623\\u0635\\u0627\\u0628\\u0639 \\u0628\\u0627\\u0631\\u062F\\u0629 \\u0648\\u0644\\u0645\\u0628\\u0627\\u062A \\u062F\\u0627\\u0641\\u064A\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0636\\u0644."
t["Cold tea and company beat hot tea alone."] = "\\u0634\\u0627\\u064A \\u0628\\u0627\\u0631\\u062F \\u0645\\u0639 \\u0635\\u062D\\u0628\\u0629 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0634\\u0627\\u064A \\u0633\\u062E\\u0646 \\u0644\\u062D\\u0627\\u0644."
t["Come back for me, %1! I need my family!"] = "\\u0627\\u0631\\u062C\\u0639\\u0644\\u064A \\u064A\\u0627 %1! \\u0628\\u062F\\u064A \\u0639\\u064A\\u0644\\u062A\\u064A!"
t["Come closer. We may have news for you."] = "\\u0642\\u0631\\u0628. \\u064A\\u0645\\u0643\\u0646 \\u0639\\u0646\\u0627 \\u0623\\u062E\\u0628\\u0627\\u0631 \\u0625\\u0644\\u0643."
t["Come here. I want to go over the plan again."] = "\\u062A\\u0639\\u0627\\u0644 \\u0644\\u0647\\u0648\\u0646. \\u0628\\u062F\\u064A \\u0631\\u0627\\u062C\\u0639 \\u0627\\u0644\\u062E\\u0637\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629."
t["Come here. Let me make sure you are really all right."] = "\\u062A\\u0639\\u0627\\u0644. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u062A\\u0623\\u0643\\u062F \\u0625\\u0646\\u0643 \\u0645\\u0646\\u064A\\u062D \\u0639\\u0646 \\u062C\\u062F."
t["Come on out, you rotten sons of bitches. I'm in a mood."] = "\\u0627\\u0637\\u0644\\u0639\\u0648\\u0627 \\u064A\\u0627 \\u0648\\u0644\\u0627\\u062F \\u0627\\u0644\\u0643\\u0644\\u0628 \\u0627\\u0644\\u0645\\u0639\\u0641\\u0646\\u064A\\u0646. \\u0645\\u0632\\u0627\\u062C\\u064A \\u0639\\u0627\\u0637\\u0644."
t["Come on out, you rotten varmints. I'm in a mood."] = "\\u0627\\u0637\\u0644\\u0639\\u0648\\u0627 \\u064A\\u0627 \\u0645\\u0639\\u0641\\u0646\\u064A\\u0646. \\u0645\\u0632\\u0627\\u062C\\u064A \\u0639\\u0627\\u0637\\u0644."
t["Come on!"] = "\\u064A\\u0644\\u0627!"
t["Come on! They hit softer than I do!"] = "\\u064A\\u0644\\u0627! \\u0647\\u0646\\u0646 \\u0628\\u064A\\u0636\\u0631\\u0628\\u0648\\u0627 \\u0623\\u062E\\u0641 \\u0645\\u0646\\u064A!"
t["Come on, fall already!"] = "\\u064A\\u0644\\u0627, \\u0648\\u0642\\u0639 \\u0628\\u0642\\u0649!"
t["Come on, little box. Say something human."] = "\\u064A\\u0644\\u0627 \\u064A\\u0627 \\u0635\\u0646\\u062F\\u0648\\u0642 \\u0635\\u063A\\u064A\\u0631. \\u0642\\u0648\\u0644 \\u0634\\u064A \\u0628\\u0634\\u0631\\u064A."
t["Come on, little things. Give us something green."] = "\\u064A\\u0644\\u0627 \\u064A\\u0627 \\u0635\\u063A\\u0627\\u0631. \\u0639\\u0637\\u0648\\u0646\\u0627 \\u0634\\u064A \\u0623\\u062E\\u0636\\u0631."
t["Come on, then!"] = "\\u062A\\u0639\\u0627\\u0644 \\u064A\\u0644\\u0627!"
t["Come on, you slippery bastard. The pan's waiting."] = "\\u062A\\u0639\\u0627\\u0644 \\u064A\\u0627 \\u0627\\u0628\\u0646 \\u0627\\u0644\\u0643\\u0644\\u0628 \\u064A\\u0627 \\u0632\\u0644\\u0642. \\u0627\\u0644\\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0646\\u0627\\u0637\\u0631\\u0629."
t["Come on, you slippery rascal. The pan's waiting."] = "\\u062A\\u0639\\u0627\\u0644 \\u064A\\u0627 \\u0645\\u0644\\u0639\\u0648\\u0646 \\u064A\\u0627 \\u0632\\u0644\\u0642. \\u0627\\u0644\\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0646\\u0627\\u0637\\u0631\\u0629."
t["Come sit with me. This part is good."] = "\\u062A\\u0639\\u0627\\u0644 \\u0627\\u0642\\u0639\\u062F \\u062C\\u0646\\u0628\\u064A. \\u0647\\u0627\\u0644\\u0642\\u0633\\u0645 \\u062D\\u0644\\u0648."
t["Comfortable. Suspiciously comfortable."] = "\\u0645\\u0631\\u064A\\u062D. \\u0645\\u0631\\u064A\\u062D \\u0628\\u0634\\u0643\\u0644 \\u0645\\u0634\\u0628\\u0648\\u0647."
t["Comfortable. Suspiciously goddamn comfortable."] = "\\u0645\\u0631\\u064A\\u062D. \\u0645\\u0631\\u064A\\u062D \\u0628\\u0634\\u0643\\u0644 \\u0645\\u0634\\u0628\\u0648\\u0647 \\u064A\\u0644\\u0639\\u0646."
t["Coming through, %1."] = "\\u0637\\u0631\\u064A\\u0642 \\u064A\\u0627 %1."
t["Community hot-meal site. Hot is aspirational, but meal sounds good."] = "\\u0645\\u0648\\u0642\\u0639 \\u0648\\u062C\\u0628\\u0627\\u062A \\u0633\\u062E\\u0646\\u0629. \\u0627\\u0644\\u0633\\u062E\\u0648\\u0646\\u0629 \\u0637\\u0645\\u0648\\u062D\\u060C \\u0628\\u0633 \\u0627\\u0644\\u0648\\u062C\\u0628\\u0629 \\u062D\\u0644\\u0648\\u0629."
t["Company sounds good. Just for a minute."] = "\\u0627\\u0644\\u0648\\u0646\\u0633 \\u062D\\u0644\\u0648. \\u0628\\u0633 \\u0644\\u062F\\u0642\\u064A\\u0642\\u0629."
t["Confidence is useful as long as we keep the exit plan."] = "\\u0627\\u0644\\u062B\\u0642\\u0629 \\u0645\\u0641\\u064A\\u062F\\u0629 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u062E\\u0637\\u0629 \\u0627\\u0644\\u0647\\u0631\\u0648\\u0628 \\u0645\\u0639\\u0646\\u0627."
t["Confirmed down."] = "\\u0648\\u0642\\u0639 \\u0623\\u0643\\u064A\\u062F."
t["Confirmed. It's not moving."] = "\\u0623\\u0643\\u064A\\u062F. \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643."
t["Contact range overloaded. Moving beyond grabbing distance."] = "\\u0645\\u062F\\u0649 \\u0627\\u0644\\u0627\\u0644\\u062A\\u062D\\u0627\\u0645 \\u0637\\u0627\\u0641\\u062D. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0645\\u0633\\u0643."
t["Contact! Keep moving!"] = "\\u0627\\u0646\\u062A\\u0628\\u0647! \\u0643\\u0645\\u0644 \\u0645\\u0634\\u064A!"
t["Contact! Zombie!"] = "\\u0627\\u0646\\u062A\\u0628\\u0647! \\u0632\\u0648\\u0645\\u0628\\u064A!"
t["Contact, close range!"] = "\\u0627\\u0646\\u062A\\u0628\\u0647\\u060C \\u0642\\u0631\\u064A\\u0628 \\u0643\\u062A\\u064A\\u0631!"
t["Conversation is permitted. Entry is a separate discussion."] = "\\u0627\\u0644\\u062D\\u0643\\u064A \\u0645\\u0633\\u0645\\u0648\\u062D. \\u0627\\u0644\\u0641\\u0648\\u062A\\u0629 \\u0645\\u0648\\u0636\\u0648\\u0639 \\u062A\\u0627\\u0646\\u064A."
t["Could be worse. I can't think how, but it could."] = "\\u0645\\u0645\\u0643\\u0646 \\u0623\\u0639\\u0648\\u0633. \\u0645\\u0648 \\u0639\\u0627\\u0631\\u0641\\u0629 \\u0643\\u064A\\u0641\\u060C \\u0628\\u0633 \\u0645\\u0645\\u0643\\u0646."
t["Could have sworn that was alive."] = "\\u0643\\u0646\\u062A \\u0631\\u062D \\u0627\\u062D\\u0644\\u0641 \\u0625\\u0646\\u0648 \\u0639\\u0627\\u064A\\u0634."
t["Could not even clear a wall. Great."] = "\\u062D\\u062A\\u0649 \\u062D\\u064A\\u0637 \\u0645\\u0627 \\u0642\\u062F\\u0631\\u062A \\u0627\\u0642\\u0637\\u0639\\u0647. \\u0639\\u0638\\u064A\\u0645."
t["Could we keep the volume a little lower? I can still hear it."] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u0648\\u0637\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A \\u0634\\u0648\\u064A\\u061F \\u0628\\u0636\\u0644 \\u0633\\u0627\\u0645\\u0639\\u062A\\u0647."
t["Could we look for a crowbar before I try that again?"] = "\\u0641\\u064A\\u0646\\u0627 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0639\\u062A\\u0644\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062C\\u0631\\u0628 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629\\u061F"
t["Could you find me a pot from one of the kitchens?"] = "\\u0641\\u064A\\u0643 \\u062A\\u062C\\u064A\\u0628\\u0644\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629 \\u0645\\u0646 \\u0634\\u064A \\u0645\\u0637\\u0628\\u062E\\u061F"
t["Could you help me find a working place to cook?"] = "\\u0641\\u064A\\u0643 \\u062A\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0644\\u0627\\u0642\\u064A \\u0645\\u062D\\u0644 \\u064A\\u0646\\u0641\\u0639 \\u0644\\u0644\\u0637\\u0628\\u062E\\u061F"
t["Count everything. We need to know exactly what is left."] = "\\u0639\\u062F \\u0643\\u0644 \\u0634\\u064A. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0639\\u0631\\u0641 \\u0628\\u0627\\u0644\\u0636\\u0628\\u0637 \\u0634\\u0648 \\u0628\\u0627\\u0642\\u064A."
t["Count it before we celebrate."] = "\\u0639\\u062F\\u0651\\u0647 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u062D\\u062A\\u0641\\u0644."
t["Count to ten after I stop breathing. Then be certain."] = "\\u0639\\u062F \\u0644\\u0644\\u0639\\u0634\\u0631\\u0629 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u064A\\u0648\\u0642\\u0641 \\u0646\\u0641\\u0633\\u064A. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u062A\\u0623\\u0643\\u062F."
t["County Emergency Services: always ready. They were. That was the trouble."] = "\\u062E\\u062F\\u0645\\u0627\\u062A \\u0627\\u0644\\u0637\\u0648\\u0627\\u0631\\u0626: \\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u062C\\u0627\\u0647\\u0632\\u064A\\u0646. \\u0648\\u0643\\u0627\\u0646\\u0648\\u0627. \\u0648\\u0647\\u0648\\u0646 \\u0643\\u0627\\u0646\\u062A \\u0627\\u0644\\u0645\\u0634\\u0643\\u0644\\u0629."
t["County health notice: keep three days of medicine. Optimistic, that."] = "\\u062A\\u0639\\u0645\\u064A\\u0645 \\u0635\\u062D\\u064A: \\u062E\\u0644\\u064A \\u0639\\u0646\\u062F\\u0643 \\u062F\\u0648\\u0627 \\u062A\\u0644\\u0627\\u062A \\u0623\\u064A\\u0627\\u0645. \\u0645\\u062A\\u0641\\u0627\\u0626\\u0644\\u064A\\u0646."
t["County morale station. Refreshments subject to availability."] = "\\u0645\\u062D\\u0637\\u0629 \\u0645\\u0639\\u0646\\u0648\\u064A\\u0627\\u062A \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629. \\u0627\\u0644\\u0645\\u0631\\u0637\\u0628\\u0627\\u062A \\u062D\\u0633\\u0628 \\u0627\\u0644\\u0645\\u062A\\u0648\\u0641\\u0631."
t["County notice says recreation maintains public morale. Roll carefully."] = "\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u062A\\u0631\\u0641\\u064A\\u0647 \\u0628\\u064A\\u0631\\u0641\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0646\\u0648\\u064A\\u0627\\u062A. \\u062F\\u062D\\u0631\\u062C \\u0628\\u062D\\u0630\\u0631."
t["Couple of drifters! Split them up!"] = "\\u062A\\u0646\\u064A\\u0646 \\u0636\\u0627\\u064A\\u0639\\u064A\\u0646! \\u0641\\u0631\\u0642\\u0646!"
t["Courage is learned one bad day at a time."] = "\\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629 \\u0628\\u062A\\u0646\\u062A\\u0639\\u0644\\u0645 \\u064A\\u0648\\u0645 \\u0639\\u0627\\u0637\\u0644 \\u0648\\u0631\\u0627 \\u064A\\u0648\\u0645 \\u0639\\u0627\\u0637\\u0644."
t["Cover me, I'm moving!"] = "\\u063A\\u0637\\u064A\\u0646\\u064A, \\u0639\\u0645 \\u0627\\u062A\\u062D\\u0631\\u0643!"
t["Cover the path a second, would you?"] = "\\u063A\\u0637\\u064A\\u0644\\u064A \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u062B\\u0627\\u0646\\u064A\\u0629\\u060C \\u0645\\u0645\\u0643\\u0646\\u061F"
t["Crap, that looks bad. Hold still."] = "\\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631\\u060C \\u0634\\u0643\\u0644\\u0647\\u0627 \\u0639\\u0627\\u0637\\u0644. \\u062B\\u0628\\u062A."
t["Crap. My hands won't listen. Stay close while I breathe."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627. \\u0625\\u064A\\u062F\\u064A\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u064A\\u0637\\u064A\\u0639\\u0648\\u0646\\u064A. \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u0644\\u0622\\u062E\\u062F \\u0646\\u0641\\u0633\\u064A."
t["Crap. That's another fish with a story about me."] = "\\u064A\\u0627 \\u0632\\u0641\\u062A. \\u0647\\u064A \\u0633\\u0645\\u0643\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629 \\u0639\\u0646\\u062F\\u0647\\u0627 \\u0642\\u0635\\u0629 \\u0639\\u0646\\u064A."
t["Crap. Tough room, worse listeners."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627. \\u062C\\u0645\\u0647\\u0648\\u0631 \\u0635\\u0639\\u0628\\u060C \\u0648\\u0623\\u062F\\u0627\\u0646\\u0647\\u0646 \\u0623\\u0635\\u0639\\u0628."
t["Crime scene tape. Bit late to cordon off the whole county."] = "\\u0634\\u0631\\u064A\\u0637 \\u0645\\u0633\\u0631\\u062D \\u062C\\u0631\\u064A\\u0645\\u0629. \\u0645\\u062A\\u0623\\u062E\\u0631\\u064A\\u0646 \\u0634\\u0648\\u064A \\u0639\\u062A\\u0637\\u0648\\u064A\\u0642 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0644\\u0647\\u0627."
t["Critical dehydration. I need water immediately."] = "\\u062C\\u0641\\u0627\\u0641 \\u062E\\u0637\\u064A\\u0631. \\u0628\\u062F\\u064A \\u0645\\u064A \\u062D\\u0627\\u0644\\u0627\\u064B."
t["Critical fatigue. I am no longer operational."] = "\\u062A\\u0639\\u0628 \\u062E\\u0637\\u064A\\u0631. \\u0645\\u0627 \\u0639\\u062F\\u062A \\u0642\\u0627\\u062F\\u0631\\u0629 \\u0627\\u0634\\u062A\\u063A\\u0644."
t["Critical food deficit. I need a meal immediately."] = "\\u0646\\u0642\\u0635 \\u0623\\u0643\\u0644 \\u062E\\u0637\\u064A\\u0631. \\u0628\\u062F\\u064A \\u0648\\u062C\\u0628\\u0629 \\u062D\\u0627\\u0644\\u0627\\u064B."
t["Crop is mature. Collecting usable yield."] = "\\u0627\\u0644\\u0632\\u0631\\u0639 \\u0646\\u0636\\u062C. \\u0639\\u0645 \\u0644\\u0645\\u0651 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0646\\u0641\\u0639."
t["Crop loss confirmed. Clearing and replanting."] = "\\u0627\\u0644\\u0632\\u0631\\u0639 \\u0631\\u0627\\u062D \\u0623\\u0643\\u064A\\u062F. \\u0639\\u0645 \\u0646\\u0636\\u0651\\u0641 \\u0648\\u0627\\u0631\\u062C\\u0639 \\u0627\\u0632\\u0631\\u0639."
t["Crop's gone. The ground remains available for another disappointment."] = "\\u0631\\u0627\\u062D \\u0627\\u0644\\u0632\\u0631\\u0639. \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0644\\u0633\\u0627 \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0644\\u062E\\u064A\\u0628\\u0629 \\u0623\\u0645\\u0644 \\u062C\\u062F\\u064A\\u062F\\u0629."
t["Crossed, with more effort than forecast."] = "\\u0642\\u0637\\u0639\\u062A, \\u0628\\u062C\\u0647\\u062F \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062A\\u0648\\u0642\\u0639."
t["Crossing at %1. Check the corners."] = "\\u0631\\u062D \\u0646\\u0642\\u0637\\u0639 \\u0639\\u0646\\u062F %1. \\u0634\\u064A\\u0643 \\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627."
t["Crowd ahead. Cover the withdrawal!"] = "\\u0639\\u062C\\u0642\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u063A\\u0637\\u064A \\u0627\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628!"
t["Crowd ahead. I don't want anyone separated."] = "\\u0639\\u062C\\u0642\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0636\\u064A\\u0639 \\u0639\\u0646\\u0627."
t["Crowd ahead. Keep the exit behind us."] = "\\u0639\\u062C\\u0642\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u062E\\u0644\\u064A \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0648\\u0631\\u0627\\u0646\\u0627."
t["Crowd ahead. Make every hit count."] = "\\u0639\\u062C\\u0642\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0643\\u0644 \\u0636\\u0631\\u0628\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062C\\u064A\\u0628 \\u0646\\u062A\\u064A\\u062C\\u0629."
t["Crowd closing in! Run!"] = "\\u0627\\u0644\\u0639\\u062C\\u0642\\u0629 \\u0639\\u0645 \\u062A\\u0637\\u0628\\u0642! \\u0627\\u0631\\u0643\\u0636!"
t["Crowd contact. Conserve room and stamina."] = "\\u0639\\u062C\\u0642\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0648\\u0641\\u0631 \\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0648\\u0627\\u0644\\u0646\\u0641\\u0633."
t["Crowd incoming. Hold your nerve!"] = "\\u0639\\u062C\\u0642\\u0629 \\u062C\\u0627\\u064A\\u0629. \\u0634\\u062F \\u0623\\u0639\\u0635\\u0627\\u0628\\u0643!"
t["Crowd incoming. Keep the exit open!"] = "\\u0639\\u062C\\u0642\\u0629 \\u062C\\u0627\\u064A\\u0629. \\u062E\\u0644\\u064A \\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0645\\u0641\\u062A\\u0648\\u062D!"
t["Crowd pressure critical. Disengage."] = "\\u0627\\u0644\\u0636\\u063A\\u0637 \\u0635\\u0627\\u0631 \\u062E\\u0637\\u0631. \\u0641\\u0643 \\u0627\\u0644\\u0627\\u0634\\u062A\\u0628\\u0627\\u0643."
t["Crowded meant there was always someone to pass the salt."] = "\\u0627\\u0644\\u0632\\u062D\\u0645\\u0629 \\u0643\\u0627\\u0646\\u062A \\u064A\\u0639\\u0646\\u064A \\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0646\\u0627\\u0648\\u0644\\u0643 \\u0627\\u0644\\u0645\\u0644\\u062D."
t["Current assessment:"] = "\\u062A\\u0642\\u062F\\u064A\\u0631\\u0646\\u0627 \\u0647\\u0644\\u0623:"
t["Dairy section. Hold your breath and keep walking."] = "\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0623\\u0644\\u0628\\u0627\\u0646. \\u0627\\u062D\\u0628\\u0633 \\u0646\\u0641\\u0633\\u0643 \\u0648\\u0643\\u0645\\u0644."
t["Damn craving picked a fine time to get loud."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u062E\\u0631\\u0645\\u0629\\u060C \\u0644\\u0642\\u062A \\u0648\\u0642\\u062A\\u0647\\u0627 \\u0644\\u062A\\u0639\\u0644\\u0651\\u064A \\u0635\\u0648\\u062A\\u0647\\u0627."
t["Damn fine parking. Shame about the rest of the trip."] = "\\u0635\\u0641\\u0651\\u0629 \\u0645\\u0639\\u062A\\u0628\\u0631\\u0629 \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627. \\u0628\\u0633 \\u062E\\u0633\\u0627\\u0631\\u0629 \\u0628\\u0627\\u0642\\u064A \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631."
t["Damn it, a pair of them."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629, \\u062A\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0646."
t["Damn it, don't let both reach me!"] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629, \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u064A\\u0648\\u0635\\u0644\\u0648\\u0627 \\u0644\\u0639\\u0646\\u062F\\u064A!"
t["Damn it, one of them is here!"] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629, \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0646 \\u0647\\u0648\\u0646!"
t["Damn it. Dead at last."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629. \\u0645\\u0627\\u062A \\u0623\\u062E\\u064A\\u0631\\u0627."
t["Damn it. I need a minute before I say something worse."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u062D\\u0638. \\u0628\\u062F\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0642\\u0648\\u0644 \\u0634\\u064A \\u0623\\u0633\\u0648\\u0623."
t["Damn it. We needed this crop."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u062D\\u0638. \\u0643\\u0646\\u0627 \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646 \\u0647\\u0627\\u0644\\u0632\\u0631\\u0639."
t["Damn place still smells like bad news and disinfectant."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644\\u060C \\u0644\\u0633\\u0627 \\u0631\\u064A\\u062D\\u062A\\u0647 \\u0623\\u062E\\u0628\\u0627\\u0631 \\u0639\\u0627\\u0637\\u0644\\u0629 \\u0648\\u0645\\u0637\\u0647\\u0651\\u0631."
t["Damn thing won't drop!"] = "\\u0647\\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646 \\u0645\\u0627 \\u0628\\u062F\\u0648 \\u064A\\u0648\\u0642\\u0639!"
t["Damn, that stung. Watch your reach."] = "\\u064A\\u0644\\u0639\\u0646\\u060C \\u0648\\u062C\\u0639\\u062A\\u0646\\u064A. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0648\\u064A\\u0646 \\u0628\\u062A\\u0648\\u0635\\u0644 \\u0625\\u064A\\u062F\\u0643."
t["Damn, that's a whole group."] = "\\u064A\\u0644\\u0639\\u0646, \\u0647\\u064A \\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629."
t["Damn. It took the bait and left me a story."] = "\\u064A\\u0644\\u0639\\u0646. \\u0623\\u0643\\u0644\\u062A \\u0627\\u0644\\u0637\\u0639\\u0645 \\u0648\\u062A\\u0631\\u0643\\u062A\\u0644\\u064A \\u0642\\u0635\\u0629."
t["Dark as hell. Accurate, but dark as hell."] = "\\u0633\\u0648\\u062F\\u0627 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0632\\u0641\\u062A. \\u0635\\u062D\\u064A\\u062D\\u0629\\u060C \\u0628\\u0633 \\u0633\\u0648\\u062F\\u0627 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0632\\u0641\\u062A."
t["Dark's coming. I'll take a look at the perimeter."] = "\\u0627\\u0644\\u0639\\u062A\\u0645\\u0629 \\u062C\\u0627\\u064A\\u0629. \\u0628\\u062A\\u0637\\u0644\\u0639 \\u0639\\u0627\\u0644\\u0645\\u062D\\u064A\\u0637."
t["Dark. Accurate, but dark."] = "\\u0633\\u0648\\u062F\\u0627. \\u0635\\u062D\\u064A\\u062D\\u0629\\u060C \\u0628\\u0633 \\u0633\\u0648\\u062F\\u0627."
t["Darn craving picked a fine time to get loud."] = "\\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A \\u0647\\u0627\\u0644\\u062E\\u0631\\u0645\\u0629\\u060C \\u0644\\u0642\\u062A \\u0648\\u0642\\u062A\\u0647\\u0627 \\u0644\\u062A\\u0639\\u0644\\u0651\\u064A \\u0635\\u0648\\u062A\\u0647\\u0627."
t["Darn fine parking. Shame about the rest of the trip."] = "\\u0635\\u0641\\u0651\\u0629 \\u0645\\u0639\\u062A\\u0628\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0644\\u0647. \\u0628\\u0633 \\u062E\\u0633\\u0627\\u0631\\u0629 \\u0628\\u0627\\u0642\\u064A \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631."
t["Darn place still smells like bad news and disinfectant."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0644\\u0633\\u0627 \\u0631\\u064A\\u062D\\u062A\\u0647 \\u0623\\u062E\\u0628\\u0627\\u0631 \\u0639\\u0627\\u0637\\u0644\\u0629 \\u0648\\u0645\\u0637\\u0647\\u0651\\u0631."
t["Darn thing won't drop!"] = "\\u0647\\u0627\\u0644\\u0645\\u0639\\u062A\\u0631 \\u0645\\u0627 \\u0628\\u062F\\u0648 \\u064A\\u0648\\u0642\\u0639!"
t["Daylight helps. We should use it."] = "\\u0627\\u0644\\u0636\\u0648 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0633\\u062A\\u063A\\u0644\\u0647."
t["Daylight is nearly gone. Shelter should be the next objective."] = "\\u0627\\u0644\\u0636\\u0648 \\u0642\\u0631\\u0628 \\u064A\\u062E\\u0644\\u0635. \\u0627\\u0644\\u0645\\u0623\\u0648\\u0649 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0647\\u062F\\u0641 \\u0627\\u0644\\u062C\\u0627\\u064A."
t["Daylight on an empty street. It only shows you what is gone."] = "\\u0636\\u0648 \\u0639\\u0644\\u0649 \\u0634\\u0627\\u0631\\u0639 \\u0641\\u0627\\u0636\\u064A. \\u0628\\u0633 \\u0628\\u064A\\u0641\\u0631\\u062C\\u064A\\u0643 \\u0634\\u0648 \\u0631\\u0627\\u062D."
t["Daylight's nearly gone. I'll finish the camp check."] = "\\u0627\\u0644\\u0636\\u0648 \\u0642\\u0631\\u0628 \\u064A\\u062E\\u0644\\u0635. \\u0628\\u0643\\u0645\\u0644 \\u062C\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645."
t["Dead ahead!"] = "\\u0645\\u064A\\u062A \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627!"
t["Dead for good."] = "\\u0645\\u0627\\u062A \\u0648\\u062E\\u0644\\u0635."
t["Dehydration is slowing me down. We need water before another risk."] = "\\u0627\\u0644\\u062C\\u0641\\u0627\\u0641 \\u0639\\u0645 \\u064A\\u0628\\u0637\\u0651\\u064A\\u0646\\u064A. \\u0628\\u062F\\u0646\\u0627 \\u0645\\u064A \\u0642\\u0628\\u0644 \\u0623\\u064A \\u0645\\u062E\\u0627\\u0637\\u0631\\u0629."
t["Deja vu. Have we walked exactly this way before?"] = "\\u0643\\u0623\\u0646\\u064A \\u0634\\u0627\\u064A\\u0641\\u0629 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0628\\u0644. \\u0645\\u0634\\u064A\\u0646\\u0627 \\u0645\\u0646 \\u0647\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637 \\u0642\\u0628\\u0644\\u061F"
t["Designated emergency supply point, open twenty-four hours. Technically true."] = "\\u0646\\u0642\\u0637\\u0629 \\u062A\\u0645\\u0648\\u064A\\u0646 \\u0637\\u0648\\u0627\\u0631\\u0626\\u060C \\u0641\\u0627\\u062A\\u062D\\u0629 \\u0623\\u0631\\u0628\\u0639\\u0629 \\u0648\\u0639\\u0634\\u0631\\u064A\\u0646 \\u0633\\u0627\\u0639\\u0629. \\u0641\\u0646\\u064A\\u064B\\u0627 \\u0635\\u062D\\u064A\\u062D."
t["Detention's over. Forever."] = "\\u062E\\u0644\\u0635 \\u0627\\u0644\\u062D\\u062C\\u0632 \\u0628\\u0627\\u0644\\u0645\\u062F\\u0631\\u0633\\u0629. \\u0644\\u0644\\u0623\\u0628\\u062F."
t["Did I feed the cat before all this? I never had a cat."] = "\\u0637\\u0639\\u0645\\u064A\\u062A \\u0627\\u0644\\u0642\\u0637\\u0629 \\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F\\u061F \\u0639\\u0645\\u0631\\u064A \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u0642\\u0637\\u0629."
t["Did I lock my front door back home? Does it matter? It matters."] = "\\u0642\\u0641\\u0644\\u062A \\u0628\\u0627\\u0628 \\u0628\\u064A\\u062A\\u064A\\u061F \\u0628\\u064A\\u0641\\u0631\\u0642\\u061F \\u0628\\u064A\\u0641\\u0631\\u0642."
t["Did I lock the door? I locked the door. I'll check the door."] = "\\u0642\\u0641\\u0644\\u062A \\u0627\\u0644\\u0628\\u0627\\u0628\\u061F \\u0642\\u0641\\u0644\\u062A \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0631\\u062D \\u0627\\u062A\\u0623\\u0643\\u062F \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0627\\u0628."
t["Did anyone check the back? I'll check the back."] = "\\u062D\\u062F\\u0627 \\u062A\\u0641\\u0642\\u062F \\u0648\\u0631\\u0627\\u061F \\u0623\\u0646\\u0627 \\u0628\\u062A\\u0641\\u0642\\u062F \\u0648\\u0631\\u0627."
t["Did not make it, but nothing is broken."] = "\\u0645\\u0627 \\u0632\\u0628\\u0637\\u062A, \\u0628\\u0633 \\u0645\\u0627 \\u0627\\u0646\\u0643\\u0633\\u0631 \\u0634\\u064A."
t["Did you hear that? Something in here does not feel right."] = "\\u0633\\u0645\\u0639\\u062A \\u0647\\u0627\\u062F\\u061F \\u0641\\u064A \\u0634\\u064A \\u0647\\u0648\\u0646 \\u0645\\u0648 \\u0645\\u0631\\u064A\\u062D\\u0646\\u064A."
t["Didn't help. Stay close anyway."] = "\\u0645\\u0627 \\u0646\\u0641\\u0639. \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628."
t["Didn't think so."] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u0631\\u0641\\u0629."
t["Disease identified. Applying the matching treatment."] = "\\u0639\\u0631\\u0641\\u062A \\u0627\\u0644\\u0645\\u0631\\u0636. \\u0639\\u0645 \\u062D\\u0637 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062C \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628."
t["Disease in the row. Getting the spray."] = "\\u0641\\u064A \\u0645\\u0631\\u0636 \\u0628\\u0627\\u0644\\u062E\\u0637. \\u062C\\u0627\\u064A\\u0629 \\u0628\\u0627\\u0644\\u0631\\u0634."
t["Distraction attempt one: look left. No? Noted."] = "\\u0645\\u062D\\u0627\\u0648\\u0644\\u0629 \\u0625\\u0644\\u0647\\u0627\\u0621 \\u0631\\u0642\\u0645 \\u0648\\u0627\\u062D\\u062F: \\u0627\\u062A\\u0637\\u0644\\u0639 \\u0639\\u0627\\u0644\\u064A\\u0633\\u0627\\u0631. \\u0644\\u0623\\u061F \\u0627\\u0646\\u0633\\u062C\\u0644\\u062A."
t["Do not come any closer."] = "\\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628 \\u0623\\u0643\\u062A\\u0631."
t["Do not follow me. I need some quiet."] = "\\u0644\\u0627 \\u062A\\u0644\\u062D\\u0642\\u0646\\u064A. \\u0628\\u062F\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0647\\u062F\\u0648\\u0621."
t["Do not let them box us in - keep an exit open!"] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u062D\\u0627\\u0635\\u0631\\u0648\\u0646\\u0627 - \\u062E\\u0644\\u064A \\u0645\\u062E\\u0631\\u062C \\u0645\\u0641\\u062A\\u0648\\u062D!"
t["Do not look back. Follow the escape route!"] = "\\u0644\\u0627 \\u062A\\u062A\\u0637\\u0644\\u0639 \\u0648\\u0631\\u0627\\u0643. \\u062E\\u062F \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0647\\u0631\\u0628!"
t["Do we have another supply run planned?"] = "\\u0641\\u064A \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0645\\u0648\\u0646\\u0629 \\u062A\\u0627\\u0646\\u064A \\u0628\\u0627\\u0644\\u062E\\u0637\\u0629\\u061F"
t["Do what I would do for you, %1."] = "\\u0627\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0623\\u0646\\u0627 \\u0628\\u0639\\u0645\\u0644\\u0647 \\u0639\\u0634\\u0627\\u0646\\u0643 \\u064A\\u0627 %1."
t["Does the weather ever give us a day without an argument?"] = "\\u0627\\u0644\\u0637\\u0642\\u0633 \\u0645\\u0627 \\u0628\\u064A\\u0639\\u0637\\u064A\\u0646\\u0627 \\u064A\\u0648\\u0645 \\u0628\\u0644\\u0627 \\u062E\\u0646\\u0627\\u0642\\u0629\\u061F"
t["Doing fine, %1. The dead should be worried about us."] = "\\u0645\\u0627\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644 \\u064A\\u0627 %1. \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0647\\u0646\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0644\\u0627\\u0632\\u0645 \\u064A\\u062E\\u0627\\u0641\\u0648\\u0627 \\u0645\\u0646\\u0627."
t["Doing fine. Tell me what comes next."] = "\\u062A\\u0645\\u0627\\u0645. \\u0642\\u0644\\u064A \\u0634\\u0648 \\u0627\\u0644\\u062C\\u0627\\u064A."
t["Don't call this failure. We made a life in impossible days."] = "\\u0644\\u0627 \\u062A\\u0633\\u0645\\u064A\\u0647\\u0627 \\u0641\\u0634\\u0644. \\u0639\\u0645\\u0644\\u0646\\u0627 \\u062D\\u064A\\u0627\\u0629 \\u0628\\u0623\\u064A\\u0627\\u0645 \\u0645\\u0633\\u062A\\u062D\\u064A\\u0644\\u0629."
t["Don't carry the guilt, %1. Carry what we built."] = "\\u0644\\u0627 \\u062A\\u0634\\u064A\\u0644 \\u0627\\u0644\\u0630\\u0646\\u0628 \\u064A\\u0627 %1. \\u0634\\u064A\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0645\\u0631\\u0646\\u0627\\u0647."
t["Don't come closer. Talk from where you are."] = "\\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628 \\u0623\\u0643\\u062A\\u0631. \\u0627\\u062D\\u0643\\u064A \\u0645\\u0646 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["Don't come closer. The numbers are wrong."] = "\\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628. \\u0627\\u0644\\u0639\\u062F\\u062F \\u0645\\u0648 \\u0632\\u0627\\u0628\\u0637."
t["Don't count me out yet. Please don't count me out."] = "\\u0644\\u0627 \\u062A\\u0634\\u0637\\u0628\\u0646\\u064A \\u0644\\u0633\\u0627. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0634\\u0637\\u0628\\u0646\\u064A."
t["Don't get caught between them!"] = "\\u0644\\u0627 \\u062A\\u0639\\u0644\\u0642 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646!"
t["Don't get up swinging. I'm done."] = "\\u0644\\u0627 \\u062A\\u0642\\u0648\\u0645 \\u0639\\u0645 \\u062A\\u0636\\u0631\\u0628. \\u0623\\u0646\\u0627 \\u062E\\u0644\\u0635\\u062A."
t["Don't let me hurt you, %1. I couldn't bear that."] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0623\\u0630\\u064A\\u0643 \\u064A\\u0627 %1. \\u0645\\u0627 \\u0628\\u062A\\u062D\\u0645\\u0644 \\u0647\\u0627\\u0644\\u0634\\u064A."
t["Don't let my face make you feel guilty afterward."] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0648\\u062C\\u0647\\u064A \\u064A\\u062D\\u0633\\u0633\\u0643 \\u0628\\u0627\\u0644\\u0630\\u0646\\u0628 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Don't let the last thing I see be you dying too."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0622\\u062E\\u0631 \\u0634\\u064A \\u0634\\u0648\\u0641\\u0647 \\u062A\\u0643\\u0648\\u0646 \\u0625\\u0646\\u062A \\u0639\\u0645 \\u062A\\u0645\\u0648\\u062A \\u0643\\u0645\\u0627\\u0646."
t["Don't let them pinch us! Back up!"] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u0643\\u0645\\u0634\\u0648\\u0646\\u0627! \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627!"
t["Don't let this be where you lose me!"] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0636\\u064A\\u0639 \\u0645\\u0646\\u0643 \\u0647\\u0648\\u0646!"
t["Don't let this room become my whole story."] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u062A\\u0635\\u064A\\u0631 \\u0643\\u0644 \\u062D\\u0643\\u0627\\u064A\\u062A\\u064A."
t["Don't look at me like that. I'm still in here."] = "\\u0644\\u0627 \\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0646\\u064A \\u0647\\u064A\\u0643. \\u0644\\u0633\\u0627 \\u0623\\u0646\\u0627 \\u062C\\u0648\\u0627."
t["Don't look at me like that. Somebody has to say it."] = "\\u0644\\u0627 \\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0646\\u064A \\u0647\\u064A\\u0643. \\u062D\\u062F\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0642\\u0648\\u0644\\u0647\\u0627."
t["Don't look in the beds. Just don't."] = "\\u0644\\u0627 \\u062A\\u062A\\u0637\\u0644\\u0639 \\u0628\\u0627\\u0644\\u062A\\u062E\\u0648\\u062A. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u062A\\u0637\\u0644\\u0639."
t["Don't make a fuss. Just take it, all right?"] = "\\u0628\\u0644\\u0627 \\u062D\\u0631\\u0643\\u0627\\u062A. \\u0628\\u0633 \\u062E\\u062F\\u0647, \\u0645\\u0627\\u0634\\u064A?"
t["Don't make a scene. One of them got me."] = "\\u0644\\u0627 \\u062A\\u0639\\u0645\\u0644 \\u0628\\u0644\\u0628\\u0644\\u0629. \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0646 \\u0644\\u062D\\u0642\\u0646\\u064A."
t["Don't make me a memory yet!"] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0630\\u0643\\u0631\\u0649 \\u0647\\u0644\\u0623!"
t["Don't make me choose between you and staying alive."] = "\\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u062E\\u062A\\u0627\\u0631 \\u0628\\u064A\\u0646\\u0643 \\u0648\\u0628\\u064A\\u0646 \\u0625\\u0646\\u064A \\u0636\\u0644 \\u0639\\u0627\\u064A\\u0634\\u0629."
t["Don't make that face. I'm still here."] = "\\u0644\\u0627 \\u062A\\u0639\\u0645\\u0644 \\u0647\\u0627\\u0644\\u0648\\u062C\\u0647. \\u0644\\u0633\\u0627 \\u0623\\u0646\\u0627 \\u0647\\u0648\\u0646."
t["Don't pick at it once I cover it."] = "\\u0644\\u0627 \\u062A\\u062D\\u0643 \\u0641\\u064A\\u0647\\u0627 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u063A\\u0637\\u064A\\u0647\\u0627."
t["Don't point that at us!"] = "\\u0644\\u0627 \\u062A\\u0648\\u062C\\u0651\\u0647 \\u0647\\u0627\\u062F \\u0639\\u0644\\u064A\\u0646\\u0627!"
t["Don't pull at the wound. I'll lift the cloth."] = "\\u0644\\u0627 \\u062A\\u0634\\u062F \\u0639\\u0627\\u0644\\u062C\\u0631\\u062D. \\u0623\\u0646\\u0627 \\u0628\\u0631\\u0641\\u0639 \\u0627\\u0644\\u0642\\u0645\\u0627\\u0634."
t["Don't put weight on it yet. I'll brace it."] = "\\u0644\\u0627 \\u062A\\u062F\\u0648\\u0633 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0644\\u0633\\u0627. \\u0631\\u062D \\u062B\\u0628\\u0651\\u062A\\u0647\\u0627."
t["Don't remember the sickness. Remember the road."] = "\\u0644\\u0627 \\u062A\\u062A\\u0630\\u0643\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0636. \\u062A\\u0630\\u0643\\u0631 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["Don't rush straight in - but don't leave me!"] = "\\u0644\\u0627 \\u062A\\u0646\\u062F\\u0641\\u0639 \\u0639\\u0627\\u0644\\u0647\\u0628\\u0644 - \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u062A\\u0631\\u0643\\u0646\\u064A!"
t["Don't sleep anywhere near this room."] = "\\u0644\\u0627 \\u062A\\u0646\\u0627\\u0645 \\u0642\\u0631\\u064A\\u0628 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629."
t["Don't stay here after dark for my sake."] = "\\u0644\\u0627 \\u062A\\u0636\\u0644 \\u0647\\u0648\\u0646 \\u0628\\u0639\\u062F \\u0627\\u0644\\u0639\\u062A\\u0645\\u0629 \\u0645\\u0634\\u0627\\u0646\\u064A."
t["Don't take another step."] = "\\u0648\\u0644\\u0627 \\u062E\\u0637\\u0648\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Don't tell the others. Not yet. It's a bite."] = "\\u0644\\u0627 \\u062A\\u062E\\u0628\\u0631 \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646. \\u0645\\u0648 \\u0647\\u0644\\u0623. \\u0647\\u064A \\u0639\\u0636\\u0629."
t["Don't touch anything that glows. Or hums. Or breathes."] = "\\u0644\\u0627 \\u062A\\u0644\\u0645\\u0633 \\u0634\\u064A \\u0628\\u064A\\u0644\\u0645\\u0639. \\u0623\\u0648 \\u0628\\u064A\\u0637\\u0646. \\u0623\\u0648 \\u0628\\u064A\\u062A\\u0646\\u0641\\u0633."
t["Don't try to walk that off. Let me work."] = "\\u0644\\u0627 \\u062A\\u062C\\u0631\\u0628 \\u062A\\u0645\\u0634\\u064A\\u0647\\u0627. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644."
t["Don't try to win this! Make a hole!"] = "\\u0644\\u0627 \\u062A\\u062D\\u0627\\u0648\\u0644 \\u062A\\u0631\\u0628\\u062D! \\u0627\\u0641\\u062A\\u062D \\u0641\\u062A\\u062D\\u0629!"
t["Don't turn around. I'll catch up."] = "\\u0644\\u0627 \\u062A\\u0644\\u062A\\u0641\\u062A. \\u0628\\u0644\\u062D\\u0642\\u0643."
t["Don't turn away! I'm not gone yet!"] = "\\u0644\\u0627 \\u062A\\u062F\\u064A\\u0631 \\u0636\\u0647\\u0631\\u0643! \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0631\\u062D\\u062A!"
t["Don't use my name for whatever comes after."] = "\\u0644\\u0627 \\u062A\\u0633\\u062A\\u0639\\u0645\\u0644 \\u0627\\u0633\\u0645\\u064A \\u0644\\u0644\\u064A \\u062C\\u0627\\u064A \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Don't wait for proof. This is me giving you permission."] = "\\u0644\\u0627 \\u062A\\u0633\\u062A\\u0646\\u0649 \\u062F\\u0644\\u064A\\u0644. \\u0647\\u064A \\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0639\\u0637\\u064A\\u0643 \\u0627\\u0644\\u0625\\u0630\\u0646."
t["Don't wait too long. When it's time, don't wait. Please."] = "\\u0644\\u0627 \\u062A\\u0633\\u062A\\u0646\\u0649 \\u0643\\u062A\\u064A\\u0631. \\u0644\\u0645\\u0627 \\u064A\\u062C\\u064A \\u0627\\u0644\\u0648\\u0642\\u062A\\u060C \\u0644\\u0627 \\u062A\\u0633\\u062A\\u0646\\u0649. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Don't waste another bullet on revenge."] = "\\u0644\\u0627 \\u062A\\u0636\\u064A\\u0639 \\u0631\\u0635\\u0627\\u0635\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629 \\u0639\\u0627\\u0644\\u0627\\u0646\\u062A\\u0642\\u0627\\u0645."
t["Don't you dare get bit! I've got it!"] = "\\u0625\\u064A\\u0627\\u0643 \\u062A\\u0646\\u0639\\u0636! \\u0647\\u0627\\u062F \\u0639\\u0646\\u062F\\u064A!"
t["Done. Mind the wet patch for a bit."] = "\\u062E\\u0644\\u0635\\u062A. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0644\\u0631\\u0637\\u0648\\u0628\\u0629 \\u0634\\u0648\\u064A."
t["Done. Who's next?"] = "\\u062E\\u0644\\u0635. \\u0645\\u064A\\u0646 \\u0628\\u0639\\u062F\\u0647?"
t["Door stays open enough to hear trouble."] = "\\u0627\\u0644\\u0628\\u0627\\u0628 \\u0628\\u064A\\u0636\\u0644 \\u0645\\u0641\\u062A\\u0648\\u062D \\u0634\\u0648\\u064A \\u0644\\u0623\\u0633\\u0645\\u0639 \\u0625\\u0630\\u0627 \\u0635\\u0627\\u0631 \\u0634\\u064A."
t["Doors are shut, windows are clear. We can breathe for a minute, %1."] = "\\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0645\\u0633\\u0643\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062A\\u0646\\u0641\\u0633 \\u0634\\u0648\\u064A \\u064A\\u0627 %1."
t["Double trouble! Slow one first!"] = "\\u0645\\u0635\\u064A\\u0628\\u062A\\u064A\\u0646! \\u0627\\u0644\\u0628\\u0637\\u064A\\u0621 \\u0623\\u0648\\u0644!"
t["Down and done."] = "\\u0648\\u0642\\u0639 \\u0648\\u062E\\u0644\\u0635."
t["Down. Whatever he was before, he's simpler now."] = "\\u0648\\u0642\\u0639. \\u0634\\u0648 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0642\\u0628\\u0644, \\u0647\\u0644\\u0623 \\u0635\\u0627\\u0631 \\u0623\\u0628\\u0633\\u0637."
t["Dreamt they formed a neighbourhood watch. Very strict about lawns."] = "\\u062D\\u0644\\u0645\\u062A \\u0625\\u0646\\u0647\\u0645 \\u0639\\u0645\\u0644\\u0648\\u0627 \\u0644\\u062C\\u0646\\u0629 \\u062D\\u064A. \\u0643\\u062A\\u064A\\u0631 \\u0635\\u0627\\u0631\\u0645\\u064A\\u0646 \\u0639\\u0627\\u0644\\u0639\\u0634\\u0628."
t["Dropped it!"] = "\\u0648\\u0642\\u0639\\u062A\\u0647!"
t["Dry mouth, steady feet. For now."] = "\\u062A\\u0645 \\u0646\\u0627\\u0634\\u0641 \\u0648\\u0625\\u062C\\u0631\\u064A\\u0646 \\u062B\\u0627\\u0628\\u062A\\u064A\\u0646. \\u0644\\u0647\\u0644\\u0623."
t["Dusk already. Let's check the doors before it gets dark."] = "\\u0635\\u0627\\u0631 \\u0627\\u0644\\u0645\\u063A\\u0631\\u0628. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u064A\\u0643 \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0639\\u062A\\u0645."
t["Dusk is coming. One more job, then we get inside."] = "\\u0627\\u0644\\u0645\\u063A\\u0631\\u0628 \\u062C\\u0627\\u064A. \\u0634\\u063A\\u0644\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0644\\u062C\\u0648\\u0627."
t["Dusk is coming. Stay close, all right?"] = "\\u0627\\u0644\\u0645\\u063A\\u0631\\u0628 \\u062C\\u0627\\u064A. \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628\\u060C \\u0645\\u0627\\u0634\\u064A\\u061F"
t["Dusk is coming. We should decide where we're spending the night."] = "\\u0627\\u0644\\u0645\\u063A\\u0631\\u0628 \\u062C\\u0627\\u064A. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0642\\u0631\\u0631 \\u0648\\u064A\\u0646 \\u0646\\u0628\\u0627\\u062A."
t["Dusk settles over houses that will not turn their lamps on."] = "\\u0627\\u0644\\u0645\\u063A\\u0631\\u0628 \\u0646\\u0627\\u0632\\u0644 \\u0639\\u0644\\u0649 \\u0628\\u064A\\u0648\\u062A \\u0645\\u0627 \\u0631\\u062D \\u062A\\u0636\\u0648\\u064A \\u0644\\u0645\\u0628\\u0627\\u062A\\u0647\\u0627."
t["Dusk. I'll check the doors and windows again."] = "\\u0645\\u063A\\u0631\\u0628. \\u0628\\u0634\\u064A\\u0643 \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0648\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Dusk. Let's mark the safest route home."] = "\\u0645\\u063A\\u0631\\u0628. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0639\\u0644\\u0645 \\u0623\\u0623\\u0645\\u0646 \\u0637\\u0631\\u064A\\u0642 \\u0644\\u0644\\u0628\\u064A\\u062A."
t["Dusk. Tools in, doors checked, then rest."] = "\\u0645\\u063A\\u0631\\u0628. \\u0627\\u0644\\u0639\\u062F\\u0629 \\u0644\\u062C\\u0648\\u0627\\u060C \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0645\\u0634\\u064A\\u0643\\u0629\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0631\\u0627\\u062D\\u0629."
t["Dusk. We should finish up and secure a room."] = "\\u0645\\u063A\\u0631\\u0628. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062E\\u0644\\u0635 \\u0648\\u0646\\u0623\\u0645\\u0651\\u0646 \\u063A\\u0631\\u0641\\u0629."
t["ENOUGH! Get away from me!"] = "\\u0628\\u0643\\u0641\\u064A! \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u064A!"
t["Ease off the trigger and back up!"] = "\\u0634\\u064A\\u0644 \\u0625\\u0635\\u0628\\u0639\\u0643 \\u0639\\u0646 \\u0627\\u0644\\u0632\\u0646\\u0627\\u062F \\u0648\\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627!"
t["Easy now. Do not shake the hook."] = "\\u0634\\u0648\\u064A \\u0634\\u0648\\u064A. \\u0644\\u0627 \\u062A\\u0647\\u0632 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629."
t["Easy now. I'll get water to every one."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627. \\u0627\\u0644\\u0645\\u064A \\u0631\\u062D \\u062A\\u0648\\u0635\\u0644 \\u0644\\u0643\\u0644 \\u0648\\u062D\\u062F\\u0629."
t["Easy now. No need to scare the shrubbery."] = "\\u0639\\u0645\\u0647\\u0644\\u0643. \\u0645\\u0627 \\u0641\\u064A \\u062F\\u0627\\u0639\\u064A \\u062A\\u062E\\u0648\\u0641 \\u0627\\u0644\\u0634\\u062C\\u064A\\u0631\\u0627\\u062A."
t["Easy now. This should do it."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627. \\u0647\\u064A\\u0643 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0643\\u0641\\u064A."
t["Easy on the line. Let it tire itself out."] = "\\u0634\\u0648\\u064A \\u0639\\u0627\\u0644\\u062E\\u064A\\u0637. \\u062E\\u0644\\u064A\\u0647 \\u064A\\u062A\\u0639\\u0628 \\u062D\\u0627\\u0644\\u0647."
t["Easy! I'm on your side."] = "\\u0639\\u0645\\u0647\\u0644\\u0643! \\u0623\\u0646\\u0627 \\u0645\\u0639\\u0643."
t["Easy. Friendly voice, friendly hands. I am %1."] = "\\u0639\\u0644\\u0649 \\u0645\\u0647\\u0644\\u0643. \\u0635\\u0648\\u062A \\u0631\\u0641\\u064A\\u0642\\u060C \\u0625\\u064A\\u062F\\u064A\\u0646 \\u0631\\u0641\\u064A\\u0642\\u0629. \\u0623\\u0646\\u0627 %1."
t["Easy. The worst part is peeling it loose."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627. \\u0623\\u0635\\u0639\\u0628 \\u0634\\u064A \\u062A\\u0642\\u0634\\u064A\\u0631\\u0647\\u0627."
t["Easy. We caught it. Let me help."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627. \\u0644\\u062D\\u0642\\u0646\\u0627\\u0647\\u0627. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0633\\u0627\\u0639\\u062F."
t["Eating dead people's groceries. Mostly guilt-free."] = "\\u0639\\u0645 \\u0646\\u0627\\u0643\\u0644 \\u0645\\u0648\\u0646\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0628\\u0644\\u0627 \\u062A\\u0623\\u0646\\u064A\\u0628 \\u0636\\u0645\\u064A\\u0631 \\u063A\\u0627\\u0644\\u0628\\u064B\\u0627."
t["Emergency morale supplies. Somebody planned ahead after all."] = "\\u0645\\u0624\\u0646 \\u0645\\u0639\\u0646\\u0648\\u064A\\u0627\\u062A \\u0644\\u0644\\u0637\\u0648\\u0627\\u0631\\u0626. \\u0637\\u0644\\u0639 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0645\\u062E\\u0637\\u0637."
t["Emergency motor pool instructions. Step one: locate an authorized mechanic."] = "\\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A \\u0643\\u0631\\u0627\\u062C \\u0627\\u0644\\u0637\\u0648\\u0627\\u0631\\u0626. \\u0627\\u0644\\u062E\\u0637\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649: \\u0644\\u0627\\u0642\\u064A \\u0645\\u064A\\u0643\\u0627\\u0646\\u064A\\u0643\\u064A \\u0645\\u0639\\u062A\\u0645\\u062F."
t["Emergency notice says routine appointments may be delayed. Fair assessment."] = "\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0637\\u0648\\u0627\\u0631\\u0626: \\u0627\\u0644\\u0645\\u0648\\u0627\\u0639\\u064A\\u062F \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A\\u0629 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u062A\\u0623\\u062E\\u0631. \\u062A\\u0642\\u064A\\u064A\\u0645 \\u0645\\u0646\\u0635\\u0641."
t["Emergency shelter: secure doors, controlled entry. They certainly managed that."] = "\\u0645\\u0644\\u062C\\u0623 \\u0637\\u0648\\u0627\\u0631\\u0626: \\u0623\\u0628\\u0648\\u0627\\u0628 \\u0645\\u062D\\u0643\\u0645\\u0629 \\u0648\\u062F\\u062E\\u0648\\u0644 \\u0645\\u0636\\u0628\\u0648\\u0637. \\u0647\\u064A \\u0646\\u062C\\u062D\\u0648\\u0627 \\u0641\\u064A\\u0647\\u0627."
t["Empty chamber, full crowd. I'm staying back for now."] = "\\u0627\\u0644\\u0641\\u0631\\u062F \\u0641\\u0627\\u0636\\u064A \\u0648\\u0627\\u0644\\u0639\\u062C\\u0642\\u0629 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629. \\u0628\\u0627\\u0642\\u064A\\u0629 \\u0648\\u0631\\u0627 \\u0647\\u0644\\u0623."
t["Empty hands make a short obituary. I'm finding a weapon."] = "\\u0627\\u0644\\u0625\\u064A\\u062F\\u064A\\u0646 \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A\\u0629 \\u0646\\u0639\\u0648\\u062A\\u0647\\u0627 \\u0642\\u0635\\u064A\\u0631\\u0629. \\u0639\\u0645 \\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0633\\u0644\\u0627\\u062D."
t["Empty torch. Nothing's on fire, at least."] = "\\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0641\\u0627\\u0636\\u064A. \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0642\\u0644 \\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0639\\u0645 \\u064A\\u062D\\u062A\\u0631\\u0642."
t["Empty. I need to reload before I move in."] = "\\u0641\\u0627\\u0636\\u064A. \\u0644\\u0627\\u0632\\u0645 \\u0639\\u0628\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u062A\\u0642\\u062F\\u0645."
t["Encircled. Position lost. Withdrawing."] = "\\u0645\\u062D\\u0627\\u0635\\u0631\\u0629. \\u0631\\u0627\\u062D \\u0627\\u0644\\u0645\\u0648\\u0642\\u0639. \\u0639\\u0645 \\u0627\\u0646\\u0633\\u062D\\u0628."
t["End of the world and I still feel guilty about flossing."] = "\\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0648\\u0644\\u0633\\u0627 \\u062D\\u0627\\u0633\\u0629 \\u0628\\u0627\\u0644\\u0630\\u0646\\u0628 \\u0645\\u0634\\u0627\\u0646 \\u062E\\u064A\\u0637 \\u0627\\u0644\\u0633\\u0646\\u0627\\u0646."
t["End of the world and I still feel guilty about flossing. Bullshit."] = "\\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0648\\u0644\\u0633\\u0627 \\u062D\\u0627\\u0633\\u0629 \\u0628\\u0627\\u0644\\u0630\\u0646\\u0628 \\u0645\\u0634\\u0627\\u0646 \\u062E\\u064A\\u0637 \\u0627\\u0644\\u0633\\u0646\\u0627\\u0646. \\u0634\\u0648 \\u0647\\u0627\\u0644\\u0632\\u0641\\u062A."
t["Endurance reserve is gone. Recovering first."] = "\\u0645\\u0627 \\u0636\\u0644 \\u0639\\u0646\\u062F\\u064A \\u0637\\u0627\\u0642\\u0629. \\u0644\\u0627\\u0632\\u0645 \\u0627\\u0631\\u062A\\u0627\\u062D \\u0623\\u0648\\u0644."
t["Engaging the first of two!"] = "\\u0639\\u0645 \\u0647\\u0627\\u062C\\u0645 \\u0623\\u0648\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646!"
t["Engaging the lone contact."] = "\\u0639\\u0645 \\u0647\\u0627\\u062C\\u0645 \\u0627\\u0644\\u0648\\u0627\\u062D\\u062F."
t["Engine's ours now. Let's get moving."] = "\\u0627\\u0644\\u0645\\u062D\\u0631\\u0643 \\u0635\\u0627\\u0631 \\u0625\\u0644\\u0646\\u0627 \\u0647\\u0644\\u0623. \\u064A\\u0644\\u0627 \\u0646\\u0645\\u0634\\u064A."
t["Enough blood for one day. I'm leaving."] = "\\u0628\\u0643\\u0641\\u064A \\u062F\\u0645 \\u0644\\u0644\\u064A\\u0648\\u0645. \\u0623\\u0646\\u0627 \\u0645\\u0627\\u0634\\u064A\\u0629."
t["Enough radio for now. Back to our own little world."] = "\\u0628\\u0643\\u0641\\u064A \\u0631\\u0627\\u062F\\u064A\\u0648 \\u0647\\u0644\\u0623. \\u0646\\u0631\\u062C\\u0639 \\u0644\\u062F\\u0646\\u064A\\u062A\\u0646\\u0627 \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629."
