t["Everybody's a hunter now. Nobody's a sportsman."] = "\\u0647\\u0644\\u0623 \\u0643\\u0644 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0635\\u064A\\u0627\\u062F\\u064A\\u0646. \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0646\\u062F\\u0647 \\u0631\\u0648\\u062D \\u0631\\u064A\\u0627\\u0636\\u064A\\u0629."
t["Everyone back! Stay together!"] = "\\u0643\\u0644\\u0643\\u0646 \\u0644\\u0648\\u0631\\u0627! \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627!"
t["Everyone made it. I kept counting the whole way."] = "\\u0627\\u0644\\u0643\\u0644 \\u0648\\u0635\\u0644. \\u0636\\u0644\\u064A\\u062A \\u0639\\u0645 \\u0639\\u062F \\u0637\\u0648\\u0644 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["Everyone out! I'll help clear the way!"] = "\\u0643\\u0644\\u0643\\u0646 \\u0628\\u0631\\u0627! \\u0628\\u0633\\u0627\\u0639\\u062F \\u0628\\u0641\\u062A\\u062D \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642!"
t["Everyone take a breath. I will check bandages and make sure we are all right."] = "\\u0643\\u0644\\u0643\\u0646 \\u062E\\u062F\\u0648\\u0627 \\u0646\\u0641\\u0633. \\u0631\\u062D \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0634\\u0627\\u0634 \\u0648\\u0623\\u062A\\u0637\\u0645\\u0646 \\u0639\\u0644\\u064A\\u0643\\u0646."
t["Everyone with me! Nobody gets left!"] = "\\u0643\\u0644\\u0643\\u0646 \\u0645\\u0639\\u064A! \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0628\\u0642\\u0649!"
